#[test]
fn the_library_counts_tasks_in_tasks_and_not_in_hosts() {
    for locale in Locale::ALL {
        let strings = crate::app::copy::ux_for(locale);
        let line = crate::app::copy::fill(strings.batch_library_more, &[("count", "7")]);
        assert!(
            line.contains('7'),
            "the count is filled in in {locale:?}: {line}"
        );
        match locale {
            Locale::Chinese => {
                assert!(
                    !line.contains('台'),
                    "a saved task is not counted in hosts: {line}"
                );
                assert!(
                    line.contains('条') || line.contains("个任务"),
                    "the unit is a task: {line}"
                );
            }
            Locale::English => assert!(line.contains("task"), "the unit is a task: {line}"),
        }
        assert_ne!(
            strings.batch_library_more, strings.batch_targets_more,
            "the library does not borrow the host sentence in {locale:?}"
        );
    }
}

/// The row under the library that counts the rest counts tasks, and it is the row drawn.
///
/// The wording of the constant was checked before; this holds the drawn row to it. With
/// sixty-five saved tasks the list draws sixty and says how many it left out, and that
/// sentence belongs to the library: "还有 N 个任务未列出", never a sentence about N
/// machines. The text a row is drawn with is not readable from a test window, so the
/// assertion is made on the function the drawing code builds the row's text with.
#[gpui::test]
async fn the_library_row_that_counts_the_rest_uses_the_library_sentence(cx: &mut TestAppContext) {
    let dir = TempDir::new("batch-library-more");
    seed(&dir.store(), batch_hosts());
    let batch = shellune_storage::BatchStore::at(dir.store().root());
    let mut book = batch.load_tasks_upgrading().expect("a readable book");
    for index in 0..65 {
        let command = format!("run {index:02}");
        let mut task = saved_task(&[command.as_str()], &["build-01"]);
        task.set_name(Some(format!("task {index:02}")));
        book.insert(task);
    }
    batch
        .save_tasks(&book)
        .expect("the saved tasks are written");

    let (view, cx) = hosts_view(cx, dir.store());
    cx.update(|_window, app| {
        view.update(app, |view, cx| view.capture_batch_library(cx));
    });
    cx.run_until_parked();
    assert!(
        cx.debug_bounds("batch.library.more").is_some(),
        "sixty rows are drawn and the five left over are counted"
    );

    // The row is drawn with this text: the library's own sentence, filled with the
    // number the list did not draw.
    let ux = crate::app::copy::ux();
    assert_eq!(
        crate::app::view::batch::library_more_line(ux, 5).as_ref(),
        crate::app::copy::fill(ux.batch_library_more, &[("count", "5")]).as_str(),
        "the row's text is the library's own sentence, not another list's"
    );

    for locale in Locale::ALL {
        let strings = crate::app::copy::ux_for(locale);
        let line = crate::app::view::batch::library_more_line(strings, 5);
        assert!(
            line.contains('5'),
            "the count is filled in in {locale:?}: {line}"
        );
        match locale {
            Locale::Chinese => {
                assert!(
                    line.contains("个任务"),
                    "the unit is a task in {locale:?}: {line}"
                );
                assert!(
                    !line.contains('台'),
                    "a saved task is not one of the machines: {line}"
                );
            }
            Locale::English => assert!(
                line.contains("task"),
                "the unit is a task in {locale:?}: {line}"
            ),
        }
        assert_ne!(
            line.as_ref(),
            crate::app::copy::fill(strings.batch_targets_more, &[("count", "5")]).as_str(),
            "the library does not borrow the host sentence in {locale:?}"
        );
    }
}

#[test]
fn the_diagnostics_name_the_hosts_and_carry_no_credential() {
    let task = saved_task(&["uptime"], &["build-01"]);
    let confirmed = task.confirm(1_700_000_000).expect("a confirmable task");
    let mut run = shellune_core::BatchRun::planned(
        &confirmed,
        shellune_core::BatchRunId::new(),
        1_700_000_000,
    );
    let host = run.hosts()[0].target().host_id();
    for kind in [
        shellune_core::BatchEventKind::RunStarted {
            hosts: 1,
            steps: 1,
            concurrency: 1,
        },
        shellune_core::BatchEventKind::StepFinished {
            host,
            step: 0,
            state: shellune_core::StepState::Failed,
            exit: Some(255),
            detail: Some("ssh://deploy:hunter2@192.0.2.11:22 said password=hunter2".to_owned()),
        },
        shellune_core::BatchEventKind::HostFinished {
            host,
            state: shellune_core::HostState::Failed,
            detail: Some("permission denied for deploy:hunter2@192.0.2.11".to_owned()),
        },
    ] {
        run.apply(&shellune_core::BatchEvent::new(0, 1_700_000_000, kind))
            .expect("the run accepts its own history");
    }
    let text = crate::app::view::batch::batch_diagnostics(&run);
    assert!(
        text.contains("build-01"),
        "the host is named so a reader knows where it was: {text}"
    );
    assert!(
        text.contains("192.0.2.11:22"),
        "the address is there, because what failed is the connection: {text}"
    );
    assert!(
        text.contains(&copy::ux().batch_exit.replace("{code}", "255")),
        "the exit status is part of the record: {text}"
    );
    assert!(!text.contains("hunter2"), "no secret leaves: {text}");
    assert!(
        text.contains("password=<hidden>"),
        "the name of the pair stays so a reader knows what was wrong, and only its value goes: {text}"
    );
}

#[test]
fn a_route_names_why_a_host_cannot_be_reached() {
    use crate::app::batch::StoredRoutes;
    use shellune_ssh::batch::RouteSource;

    let book = HostBook::from_hosts(batch_hosts()).expect("distinct hosts");
    let trust = shellune_storage::HostTrust::new();
    let secrets = std::sync::Arc::new(shellune_storage::MemorySecrets::new());
    let routes = StoredRoutes::new(&book, &trust, secrets.clone());
    let defaults = shellune_core::ConnectionDefaults::default();
    let target =
        shellune_core::BatchTarget::snapshot(&book.hosts()[0], defaults).expect("snapshot");

    // The host is saved, but nothing is saved to sign in with: the route says so
    // instead of dialling without a credential.
    let error = routes
        .take_route(&target)
        .err()
        .expect("no credential is a refusal");
    assert!(error.contains("build-01"), "{error}");

    // A host that is no longer saved cannot be reached from a snapshot of it.
    let mut shrunk = book.clone();
    shrunk
        .remove(book.hosts()[0].id())
        .expect("the host is saved");
    let routes = StoredRoutes::new(&shrunk, &trust, secrets);
    let error = routes
        .take_route(&target)
        .err()
        .expect("a missing host is a refusal");
    assert!(!error.is_empty());
}

