#[gpui::test]
async fn the_send_warning_is_drawn_once_before_the_first_frame(cx: &mut TestAppContext) {
    // A send that fails before the picture arrives: the status card already carries
    // the sentence, so the strip that sits over a picture must not repeat it (R18).
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let (link, _log) = ScriptedLink::new(Vec::new());
    let record = desktop_record("desk");
    let id = mount_scripted_desktop(&view, cx, &record, link);
    let reason = crate::app::desktop::LinkError::State.reason();
    cx.update(|_window, cx| {
        view.update(cx, |view, cx| {
            if let Some(pane) = view.desktop_of(id).cloned() {
                pane.update(cx, |pane, cx| pane.show_send_problem(&reason, cx));
            }
        });
    });
    cx.run_until_parked();
    redraw(cx);

    assert!(
        cx.debug_bounds("desktop.status").is_some(),
        "the card explains the session before any picture"
    );
    assert!(
        cx.debug_bounds("desktop.notice").is_none(),
        "the same sentence is not drawn twice while there is no picture"
    );
}

#[gpui::test]
async fn the_zoom_control_scales_the_picture_and_the_pointer_follows_it(cx: &mut TestAppContext) {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let desktop = (1600u32, 900u32);
    let (link, log) = ScriptedLink::new(vec![
        LinkEvent::State {
            state: LinkState::Connected,
            failure: LinkFailure::None,
            detail: 0,
            reason: String::new(),
        },
        LinkEvent::Frame(solid(0, 0, 1600, 900, desktop, [7, 7, 7, 255])),
    ]);
    let record = desktop_record("desk");
    let id = mount_scripted_desktop(&view, cx, &record, link);
    assert!(
        cx.debug_bounds("desktop.picture").is_none(),
        "the fit step draws the whole pane, not a placed rectangle"
    );

    let larger = bounds_of(cx, "desktop.zoom.in").center();
    cx.simulate_click(larger, Modifiers::default());
    cx.run_until_parked();

    let (zoom, pan) = cx.update(|_window, app| {
        let pane = view
            .read(app)
            .desktop_of(id)
            .expect("the surface is mounted")
            .read(app);
        (pane.zoom(), pane.pan())
    });
    assert_eq!(
        zoom,
        crate::app::desktop::DesktopZoom::Percent(200),
        "the larger control is one step in on the ladder"
    );
    let surface = bounds_of(cx, "desktop.surface");
    let drawn = bounds_of(cx, "desktop.picture");
    let expected = crate::app::desktop::content_rect_in(
        surface,
        desktop,
        crate::app::desktop::DesktopZoom::Percent(200),
        pan,
    );
    assert!(
        (f32::from(drawn.size.width) - f32::from(expected.size.width)).abs() < 1.0
            && (f32::from(drawn.size.height) - f32::from(expected.size.height)).abs() < 1.0,
        "the picture is drawn in the rectangle the pointer is mapped through: {drawn:?} was {expected:?}"
    );
    assert!(
        drawn.size.width > surface.size.width,
        "a zoom step larger than the pane is cropped by it rather than shrunk back"
    );

    // The centre of the space is the centre of the remote desktop at any zoom.
    let centre = surface.center();
    cx.simulate_mouse_down(centre, MouseButton::Left, Modifiers::default());
    let (x, y, _buttons) = last_pointer(&log);
    assert_eq!(
        (x, y),
        (800, 450),
        "a click at the centre of a zoomed picture is the centre of the desktop"
    );
    cx.simulate_mouse_up(centre, MouseButton::Left, Modifiers::default());

    // Smaller steps back to the fit, and the fit is the whole desktop again.
    let smaller = bounds_of(cx, "desktop.zoom.out").center();
    for _ in 0..crate::app::desktop::DesktopZoom::LADDER.len() {
        cx.simulate_click(smaller, Modifiers::default());
        cx.run_until_parked();
    }
    let zoom = cx.update(|_window, app| {
        view.read(app)
            .desktop_of(id)
            .expect("the surface is mounted")
            .read(app)
            .zoom()
    });
    assert_eq!(
        zoom,
        crate::app::desktop::DesktopZoom::Fit,
        "a fit picture is where zooming out ends"
    );
}

#[gpui::test]
async fn a_certificate_that_may_not_be_trusted_is_refused_at_once_and_releases_the_worker(
    cx: &mut TestAppContext,
) {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let (link, log) = ScriptedLink::new(vec![LinkEvent::Certificate {
        request_id: 9,
        host: "rdp.example.com".to_owned(),
        subject: "CN=rdp".to_owned(),
        issuer: "CN=ca".to_owned(),
        fingerprint: "AA:BB".to_owned(),
        flags: 1,
    }]);
    let record = desktop_record_rejecting_certificates("desk");
    let id = mount_scripted_desktop(&view, cx, &record, link);

    let log = log.lock().expect("the log is not poisoned").clone();
    assert_eq!(
        log.answers,
        vec![(9, false)],
        "the refusal reached the server, with the request id it asked about"
    );
    assert_eq!(
        log.shutdowns, 1,
        "the worker is stopped instead of being held while the server waits"
    );
    let (state, phase, stage) = cx.update(|_window, app| {
        let view = view.read(app);
        let pane = view
            .desktop_of(id)
            .expect("the surface is mounted")
            .read(app);
        (
            view.workspace()
                .session(id)
                .map(|session| session.state().clone()),
            pane.phase().clone(),
            pane.failed_stage(),
        )
    });
    assert_eq!(
        state,
        Some(SessionState::Failed(SessionFailure::HostKeyRejected)),
        "the record says the certificate was refused"
    );
    assert!(
        matches!(phase, crate::app::view::DesktopPhase::Ended(_)),
        "the pane ended instead of staying in a connecting step"
    );
    assert_eq!(
        stage,
        Some(crate::app::view::DesktopStage::VerifyingCertificate),
        "the step it stopped on is the one it was on"
    );
}

#[gpui::test]
async fn refusing_the_certificate_on_screen_answers_the_server_and_releases_the_connection(
    cx: &mut TestAppContext,
) {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let (link, log) = ScriptedLink::new(vec![LinkEvent::Certificate {
        request_id: 4,
        host: "rdp.example.com".to_owned(),
        subject: "CN=rdp".to_owned(),
        issuer: "CN=ca".to_owned(),
        fingerprint: "CC:DD".to_owned(),
        flags: 0,
    }]);
    let record = desktop_record("desk");
    let id = mount_scripted_desktop(&view, cx, &record, link);
    assert!(
        cx.debug_bounds("desktop.certificate").is_some(),
        "the question is on screen before an answer is given"
    );

    let reject = bounds_of(cx, "desktop.certificate.reject").center();
    cx.simulate_click(reject, Modifiers::default());
    cx.run_until_parked();

    let log = log.lock().expect("the log is not poisoned").clone();
    assert_eq!(log.answers, vec![(4, false)], "the answer the user gave");
    assert_eq!(
        log.shutdowns, 1,
        "a refused certificate does not leave the worker holding the connection"
    );
    let state = cx.update(|_window, app| {
        view.read(app)
            .workspace()
            .session(id)
            .map(|session| session.state().clone())
    });
    assert_eq!(
        state,
        Some(SessionState::Failed(SessionFailure::HostKeyRejected))
    );
}

#[gpui::test]
async fn a_clipboard_that_cannot_be_sent_is_stated_over_the_live_picture(cx: &mut TestAppContext) {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let desktop = (1600u32, 900u32);
    let (link, _log) = ScriptedLink::failing_after(
        vec![
            LinkEvent::State {
                state: LinkState::Connected,
                failure: LinkFailure::None,
                detail: 0,
                reason: String::new(),
            },
            LinkEvent::Frame(solid(0, 0, 1600, 900, desktop, [3, 3, 3, 255])),
        ],
        crate::app::desktop::LinkError::State,
    );
    let feed = link.feed();
    let record = desktop_record("desk");
    let id = mount_scripted_desktop(&view, cx, &record, link);
    assert!(
        cx.debug_bounds("desktop.notice").is_none(),
        "nothing is wrong before anything was sent"
    );

    // The link refuses every send, so this paste cannot reach the remote side. It
    // used to be dropped without a word because the only place the sentence was
    // drawn is hidden by the picture itself.
    focus_desktop(&view, cx, id);
    cx.write_to_clipboard(ClipboardItem::new_string("pasted".to_owned()));
    cx.simulate_keystrokes("ctrl-v");
    cx.run_until_parked();
    redraw(cx);

    let notice = bounds_of(cx, "desktop.notice");
    assert!(
        notice.size.width > px(0.0) && notice.size.height > px(0.0),
        "the sentence is drawn beside the picture that is already on screen"
    );
    // The next frame is not an answer to the failed send: it must not take the
    // sentence away before it can be read.
    feed.feed(vec![LinkEvent::Frame(solid(
        0,
        0,
        8,
        8,
        desktop,
        [9, 9, 9, 255],
    ))]);
    pump_desktop(&view, cx, id);
    redraw(cx);
    assert!(
        cx.debug_bounds("desktop.notice").is_some(),
        "a frame that arrived does not clear a send that did not"
    );
    assert!(cx.update(|_window, app| {
        view.read(app)
            .desktop_of(id)
            .expect("the surface is mounted")
            .read(app)
            .is_live()
    }));
}

// ---------------------------------------------------------------------------
// The clipboard a desktop shares, the paste shortcut and the session's notices
// (R1-R6 of the clipboard requirement)
// ---------------------------------------------------------------------------

/// The events of a live session with a picture, for the clipboard tests.
fn live_desktop_events() -> Vec<LinkEvent> {
    vec![
        LinkEvent::State {
            state: LinkState::Connected,
            failure: LinkFailure::None,
            detail: 0,
            reason: String::new(),
        },
        LinkEvent::Frame(solid(0, 0, 640, 400, (640, 400), [5, 6, 7, 255])),
    ]
}

/// A saved VNC connection, with the clipboard on or off.
fn vnc_record_sharing(name: &str, clipboard: bool) -> shellune_core::ConnectionRecord {
    let mut config =
        shellune_core::VncConfig::new(name, "vnc.example.com").expect("a valid VNC record");
    config.set_clipboard(clipboard);
    shellune_core::ConnectionRecord::Vnc(config)
}

/// A saved RDP connection, with the clipboard on or off.
fn rdp_record_sharing(name: &str, clipboard: bool) -> shellune_core::ConnectionRecord {
    let mut config = shellune_core::RdpConfig::new(name, "rdp.example.com", Some("desk"))
        .expect("a valid RDP record");
    config.set_clipboard(clipboard);
    shellune_core::ConnectionRecord::Rdp(config)
}

/// Everything the pane sent so far.
fn sent(
    log: &std::sync::Arc<std::sync::Mutex<crate::app::desktop::scripted::Log>>,
) -> Vec<DesktopInput> {
    log.lock().expect("the log is not poisoned").inputs.clone()
}

/// The clipboard offers the pane sent so far, each as its kinds.
fn offers(
    log: &std::sync::Arc<std::sync::Mutex<crate::app::desktop::scripted::Log>>,
) -> Vec<Vec<crate::app::desktop::ClipboardKind>> {
    log.lock()
        .expect("the log is not poisoned")
        .clipboard
        .iter()
        .map(|entries| entries.iter().map(|entry| entry.kind).collect())
        .collect()
}

/// Releases a key the way the window reports it.
fn release_key(cx: &mut VisualTestContext, keystroke: &str) {
    cx.simulate_event(gpui::KeyUpEvent {
        keystroke: gpui::Keystroke::parse(keystroke).expect("a keystroke"),
    });
}

/// A small PNG file, so a test can put a picture on the clipboard.
fn png_picture() -> Vec<u8> {
    let picture = image::RgbaImage::from_fn(3, 2, |x, y| {
        image::Rgba([(x * 80) as u8, (y * 120) as u8, 200, 255])
    });
    let mut png = Vec::new();
    image::DynamicImage::ImageRgba8(picture)
        .write_to(&mut std::io::Cursor::new(&mut png), image::ImageFormat::Png)
        .expect("the picture encodes");
    png
}

/// Gives the desktop pane the keyboard and draws the frame that reports it, which is
/// when the window tells the pane it took the keyboard.
///
/// The window is made the active one first: a test window starts inactive, and an
/// inactive window reports no focus to anything in it.
fn focus_desktop_drawn(view: &Entity<ShelluneView>, cx: &mut VisualTestContext, id: SessionId) {
    cx.update(|window, _app| window.activate_window());
    cx.run_until_parked();
    focus_desktop(view, cx, id);
    redraw(cx);
    cx.run_until_parked();
}

/// Takes the keyboard away from everything and draws the frame that reports it.
fn blur_drawn(cx: &mut VisualTestContext) {
    cx.update(|window, _app| window.blur());
    redraw(cx);
    cx.run_until_parked();
}

/// The desktop pane's notices, in the order they are on screen.
fn desktop_notices(
    view: &Entity<ShelluneView>,
    cx: &mut VisualTestContext,
    id: SessionId,
) -> Vec<crate::app::view::DesktopNotice> {
    cx.update(|_window, app| {
        view.read(app)
            .desktop_of(id)
            .expect("the surface is mounted")
            .read(app)
            .notices()
    })
}

#[gpui::test]
async fn the_paste_shortcut_offers_the_clipboard_and_then_sends_the_shortcut_itself(
    cx: &mut TestAppContext,
) {
    use crate::app::desktop::{CONTROL_LEFT, ClipboardEntry, key_codes};

    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let (link, log) = ScriptedLink::new(live_desktop_events());
    let id = mount_scripted_desktop(&view, cx, &desktop_record("desk"), link);
    focus_desktop_drawn(&view, cx, id);
    let before = sent(&log).len();

    cx.write_to_clipboard(ClipboardItem::new_string("粘贴 this".to_owned()));
    cx.simulate_keystrokes("ctrl-v");
    release_key(cx, "ctrl-v");
    cx.simulate_modifiers_change(Modifiers::none());

    let v = key_codes("v").expect("v is a key");
    assert_eq!(
        sent(&log)[before..],
        [
            DesktopInput::Clipboard(vec![ClipboardEntry::text("粘贴 this")]),
            DesktopInput::Key {
                codes: CONTROL_LEFT,
                down: true
            },
            DesktopInput::Key {
                codes: v,
                down: true
            },
            DesktopInput::Key {
                codes: v,
                down: false
            },
            DesktopInput::Key {
                codes: CONTROL_LEFT,
                down: false
            },
        ],
        "the clipboard goes first, then Ctrl+V itself, and Control is let go with the user's"
    );

    // The same content again is not offered again: the remote side already holds it,
    // and the shortcut still goes so the remote program pastes it.
    let before = sent(&log).len();
    cx.simulate_keystrokes("ctrl-v");
    release_key(cx, "ctrl-v");
    cx.simulate_modifiers_change(Modifiers::none());
    let again = sent(&log)[before..].to_vec();
    assert!(
        !again
            .iter()
            .any(|input| matches!(input, DesktopInput::Clipboard(_))),
        "content already offered is not offered twice: {again:?}"
    );
    assert_eq!(again.len(), 4, "Control, V, V up, Control up: {again:?}");
}

#[gpui::test]
async fn with_the_clipboard_off_the_paste_shortcut_still_reaches_the_remote_side(
    cx: &mut TestAppContext,
) {
    use crate::app::desktop::{CONTROL_LEFT, key_codes};

    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let (link, log) = ScriptedLink::new(live_desktop_events());
    let record = vnc_record_sharing("vnc", false);
    let id = mount_scripted_desktop(&view, cx, &record, link);
    cx.write_to_clipboard(ClipboardItem::new_string("stays here".to_owned()));
    focus_desktop_drawn(&view, cx, id);
    cx.simulate_keystrokes("ctrl-v");

    let inputs = sent(&log);
    assert!(
        log.lock()
            .expect("the log is not poisoned")
            .clipboard
            .is_empty(),
        "a connection with sharing off offers nothing, on focus or on paste"
    );
    let v = key_codes("v").expect("v is a key");
    assert_eq!(
        inputs,
        [
            DesktopInput::Key {
                codes: CONTROL_LEFT,
                down: true
            },
            DesktopInput::Key {
                codes: v,
                down: true
            },
        ],
        "the shortcut still goes, so the remote program pastes its own clipboard"
    );
}

#[gpui::test]
async fn focusing_the_picture_offers_the_clipboard_once_and_again_only_when_it_changed(
    cx: &mut TestAppContext,
) {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let (link, log) = ScriptedLink::new(live_desktop_events());
    let id = mount_scripted_desktop(&view, cx, &desktop_record("desk"), link);
    let text = vec![crate::app::desktop::ClipboardKind::Text];

    cx.write_to_clipboard(ClipboardItem::new_string("first".to_owned()));
    focus_desktop_drawn(&view, cx, id);
    assert_eq!(
        offers(&log),
        vec![text.clone()],
        "taking the keyboard offers what this computer holds"
    );

    // Leaving and coming back with the same clipboard offers nothing new.
    blur_drawn(cx);
    focus_desktop_drawn(&view, cx, id);
    assert_eq!(
        offers(&log).len(),
        1,
        "the same content is not offered twice"
    );

    // A new copy elsewhere is offered the next time the picture is focused.
    blur_drawn(cx);
    cx.write_to_clipboard(ClipboardItem::new_string("second".to_owned()));
    focus_desktop_drawn(&view, cx, id);
    let last = log
        .lock()
        .expect("the log is not poisoned")
        .clipboard
        .last()
        .cloned();
    assert_eq!(
        last,
        Some(vec![crate::app::desktop::ClipboardEntry::text("second")])
    );

    // The window coming back to the front with the picture focused offers a copy
    // made in another application meanwhile.
    cx.deactivate_window();
    cx.write_to_clipboard(ClipboardItem::new_string("from another app".to_owned()));
    cx.update(|window, _app| window.activate_window());
    cx.run_until_parked();
    let last = log
        .lock()
        .expect("the log is not poisoned")
        .clipboard
        .last()
        .cloned();
    assert_eq!(
        last,
        Some(vec![crate::app::desktop::ClipboardEntry::text(
            "from another app"
        )]),
        "reactivating the window offers the new clipboard"
    );
    assert_eq!(offers(&log).len(), 3);
}

#[gpui::test]
async fn a_picture_on_this_clipboard_is_offered_as_png_and_dib(cx: &mut TestAppContext) {
    use crate::app::desktop::ClipboardKind;

    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let (link, log) = ScriptedLink::new(live_desktop_events());
    let id = mount_scripted_desktop(&view, cx, &desktop_record("desk"), link);
    let png = png_picture();
    cx.write_to_clipboard(ClipboardItem::new_entries(vec![
        gpui::ClipboardEntry::from("a caption".to_owned()),
        gpui::ClipboardEntry::Image(gpui::Image::from_bytes(gpui::ImageFormat::Png, png.clone())),
    ]));
    focus_desktop_drawn(&view, cx, id);

    let offered = log
        .lock()
        .expect("the log is not poisoned")
        .clipboard
        .last()
        .cloned()
        .expect("the clipboard was offered");
    let kinds: Vec<ClipboardKind> = offered.iter().map(|entry| entry.kind).collect();
    assert_eq!(
        kinds,
        vec![ClipboardKind::Text, ClipboardKind::Png, ClipboardKind::Dib],
        "text and picture both go, the picture in the two forms Windows programs paste"
    );
    assert_eq!(offered[1].bytes, png, "a PNG is passed on as it was");
}

#[gpui::test]
async fn what_the_remote_side_copies_lands_on_this_clipboard_and_is_not_offered_back(
    cx: &mut TestAppContext,
) {
    use crate::app::desktop::ClipboardEntry;

    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let (link, log) = ScriptedLink::new(live_desktop_events());
    let feed = link.feed();
    let id = mount_scripted_desktop(&view, cx, &desktop_record("desk"), link);
    focus_desktop_drawn(&view, cx, id);

    // Text alone.
    feed.feed(vec![LinkEvent::Clipboard {
        entries: vec![ClipboardEntry::text("远端 text")],
    }]);
    pump_desktop(&view, cx, id);
    assert_eq!(
        cx.read_from_clipboard().and_then(|item| item.text()),
        Some("远端 text".to_owned())
    );

    // A picture alone, as a DIB: it is pasted here as PNG.
    let picture = image::RgbaImage::from_pixel(2, 2, image::Rgba([10, 200, 30, 255]));
    let dib = crate::app::desktop_clipboard::rgba_to_dib(&picture).expect("a DIB");
    feed.feed(vec![LinkEvent::Clipboard {
        entries: vec![ClipboardEntry::dib(dib.clone())],
    }]);
    pump_desktop(&view, cx, id);
    let item = cx
        .read_from_clipboard()
        .expect("the picture is on the clipboard");
    let image = item
        .entries()
        .iter()
        .find_map(|entry| match entry {
            gpui::ClipboardEntry::Image(image) => Some(image.clone()),
            _ => None,
        })
        .expect("an image entry");
    assert_eq!(image.format, gpui::ImageFormat::Png);
    let decoded = image::load_from_memory_with_format(&image.bytes, image::ImageFormat::Png)
        .expect("a PNG")
        .to_rgba8();
    assert_eq!(decoded, picture, "the remote picture, pixel for pixel");
    assert_eq!(item.text(), None);

    // Text and picture together become one item holding both.
    feed.feed(vec![LinkEvent::Clipboard {
        entries: vec![ClipboardEntry::text("caption"), ClipboardEntry::dib(dib)],
    }]);
    pump_desktop(&view, cx, id);
    let item = cx
        .read_from_clipboard()
        .expect("something is on the clipboard");
    assert_eq!(item.text(), Some("caption".to_owned()));
    assert!(
        item.entries()
            .iter()
            .any(|entry| matches!(entry, gpui::ClipboardEntry::Image(_))),
        "the picture is beside the text"
    );

    // Coming back to the picture does not send the remote side its own copy.
    blur_drawn(cx);
    focus_desktop_drawn(&view, cx, id);
    cx.simulate_keystrokes("ctrl-v");
    assert!(
        log.lock()
            .expect("the log is not poisoned")
            .clipboard
            .is_empty(),
        "what came from the remote side is never offered back to it"
    );
}

/// The send warning of the desktop pane, when one is up.
fn desktop_send_problem(
    view: &Entity<ShelluneView>,
    cx: &mut VisualTestContext,
    id: SessionId,
) -> Option<String> {
    cx.update(|_window, app| {
        view.read(app)
            .desktop_of(id)
            .expect("the surface is mounted")
            .read(app)
            .send_problem()
            .map(str::to_owned)
    })
}

#[gpui::test]
async fn a_session_still_connecting_is_offered_the_clipboard_when_it_goes_live(
    cx: &mut TestAppContext,
) {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let connected = LinkEvent::State {
        state: LinkState::Connected,
        failure: LinkFailure::None,
        detail: 0,
        reason: String::new(),
    };
    let (link, log) = ScriptedLink::new(vec![connected]);
    let feed = link.feed();
    let id = mount_scripted_desktop(&view, cx, &desktop_record("desk"), link);
    cx.write_to_clipboard(ClipboardItem::new_string(
        "copied while connecting".to_owned(),
    ));

    // The picture takes the keyboard before the first frame: the session cannot
    // take an offer yet, so nothing is read or queued.
    focus_desktop_drawn(&view, cx, id);
    assert!(
        offers(&log).is_empty(),
        "nothing is offered before the session is live"
    );

    // The first frame makes it live while the picture still holds the keyboard -
    // no focus event follows, as after a reconnect - and the clipboard goes then.
    feed.feed(vec![LinkEvent::Frame(solid(
        0,
        0,
        640,
        400,
        (640, 400),
        [5, 6, 7, 255],
    ))]);
    pump_desktop(&view, cx, id);
    redraw(cx);
    cx.run_until_parked();
    let last = log
        .lock()
        .expect("the log is not poisoned")
        .clipboard
        .last()
        .cloned();
    assert_eq!(
        last,
        Some(vec![crate::app::desktop::ClipboardEntry::text(
            "copied while connecting"
        )]),
        "going live with the keyboard offers this computer's clipboard"
    );
    redraw(cx);
    cx.run_until_parked();
    assert_eq!(offers(&log).len(), 1, "once, not on every frame");
}

#[gpui::test]
async fn focusing_a_session_still_connecting_raises_no_send_warning(cx: &mut TestAppContext) {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let connected = LinkEvent::State {
        state: LinkState::Connected,
        failure: LinkFailure::None,
        detail: 0,
        reason: String::new(),
    };
    // The native link refuses a clipboard offer with a state error until the
    // session is connected; this one refuses every send that way.
    let (link, log) =
        ScriptedLink::failing_after(vec![connected], crate::app::desktop::LinkError::State);
    let id = mount_scripted_desktop(&view, cx, &desktop_record("desk"), link);
    cx.write_to_clipboard(ClipboardItem::new_string("waiting".to_owned()));

    focus_desktop_drawn(&view, cx, id);
    cx.deactivate_window();
    cx.update(|window, _app| window.activate_window());
    cx.run_until_parked();
    pump_desktop(&view, cx, id);
    redraw(cx);

    assert_eq!(
        desktop_send_problem(&view, cx, id),
        None,
        "the user sent nothing, so the connecting card says nothing failed"
    );
    assert!(sent(&log).is_empty());
}

/// Elsewhere than macOS the Windows or Super key is this computer's: it is not
/// forwarded, so a key pressed with it is not sent as its bare letter, and Super+V
/// is not the paste shortcut.
#[cfg(not(target_os = "macos"))]
#[gpui::test]
async fn a_key_pressed_with_the_super_key_stays_on_this_computer(cx: &mut TestAppContext) {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let (link, log) = ScriptedLink::new(live_desktop_events());
    let id = mount_scripted_desktop(&view, cx, &desktop_record("desk"), link);
    focus_desktop_drawn(&view, cx, id);
    cx.write_to_clipboard(ClipboardItem::new_string("not this way".to_owned()));
    let before = sent(&log).len();

    cx.simulate_keystrokes("super-v super-a");

    assert_eq!(
        sent(&log)[before..],
        [],
        "no offer and no bare letter reach the remote side"
    );
}

