#[gpui::test]
async fn each_notice_is_shown_once_per_session_and_a_ready_clipboard_withdraws_the_refusal(
    cx: &mut TestAppContext,
) {
    use crate::app::desktop::{ClipboardKind, DriveProblem, Notice};
    use crate::app::view::DesktopNotice;

    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let (link, _log) = ScriptedLink::new(live_desktop_events());
    let feed = link.feed();
    let id = mount_scripted_desktop(&view, cx, &desktop_record("desk"), link);
    assert!(desktop_notices(&view, cx, id).is_empty());

    feed.feed(vec![
        LinkEvent::Notice(Notice::DriveUnavailable(DriveProblem::Missing)),
        LinkEvent::Notice(Notice::ClipboardRefused),
        LinkEvent::Notice(Notice::ClipboardRefused),
        LinkEvent::Notice(Notice::Unknown(99)),
    ]);
    pump_desktop(&view, cx, id);
    redraw(cx);
    assert_eq!(
        desktop_notices(&view, cx, id),
        vec![
            DesktopNotice::DriveUnavailable,
            DesktopNotice::ClipboardRefused
        ],
        "a repeated notice is said once, and one this build does not know is not said"
    );
    let strip = bounds_of(cx, "desktop.notice");
    assert!(
        strip.size.width > px(0.0) && strip.size.height > px(0.0),
        "the notices are drawn over the picture"
    );
    assert!(
        cx.debug_bounds("desktop.notice.drive_unavailable")
            .is_some()
    );
    assert!(
        cx.debug_bounds("desktop.notice.clipboard_refused")
            .is_some()
    );
    let reason = ENGLISH
        .desktop_notice_drive_unavailable
        .replace("{reason}", ENGLISH.desktop_drive_missing);
    assert!(
        reason.contains("does not exist"),
        "the folder notice names its reason: {reason}"
    );

    // The clipboard becoming ready takes the refusal back.
    feed.feed(vec![LinkEvent::Notice(Notice::ClipboardReady)]);
    pump_desktop(&view, cx, id);
    assert_eq!(
        desktop_notices(&view, cx, id),
        vec![DesktopNotice::DriveUnavailable]
    );

    // Dismissed notices stay away, and a kind already shown is not shown again.
    click(cx, "desktop.notice.dismiss");
    assert!(desktop_notices(&view, cx, id).is_empty());
    feed.feed(vec![
        LinkEvent::Notice(Notice::DriveUnavailable(DriveProblem::NoAccess)),
        LinkEvent::Notice(Notice::ClipboardTooLarge(ClipboardKind::Text)),
        LinkEvent::Notice(Notice::ClipboardTooLarge(ClipboardKind::Png)),
        LinkEvent::Notice(Notice::ClipboardTooLarge(ClipboardKind::Dib)),
        LinkEvent::Notice(Notice::ClipboardLatin1Only),
        // A refused drive is a notice of its own, beside an unavailable one, and
        // either way the server refused it is the same notice.
        LinkEvent::Notice(Notice::DriveRefused(
            shellune_desktop::DriveRefusal::Declined(0xC000_0022),
        )),
        LinkEvent::Notice(Notice::DriveRefused(
            shellune_desktop::DriveRefusal::NotOpened,
        )),
    ]);
    pump_desktop(&view, cx, id);
    redraw(cx);
    assert_eq!(
        desktop_notices(&view, cx, id),
        vec![
            DesktopNotice::TextTooLarge,
            DesktopNotice::ImageTooLarge,
            DesktopNotice::ClipboardLatin1,
            DesktopNotice::DriveRefused,
        ],
        "text cut and image left out are two notices; each image form is the same one"
    );
    for selector in [
        "desktop.notice.text_too_large",
        "desktop.notice.image_too_large",
        "desktop.notice.clipboard_latin1",
        "desktop.notice.drive_refused",
    ] {
        assert!(cx.debug_bounds(selector).is_some(), "{selector} is drawn");
    }
    assert!(cx.update(|_window, app| {
        view.read(app)
            .desktop_of(id)
            .expect("the surface is mounted")
            .read(app)
            .is_live()
    }));
}

#[test]
fn a_desktop_target_carries_the_clipboard_switch_and_the_folder_to_map() {
    let mut config = shellune_core::RdpConfig::new("desk", "rdp.example.com", Some("desk"))
        .expect("a valid RDP record");
    let target = crate::app::desktop::DesktopTarget::of_record(
        &shellune_core::ConnectionRecord::Rdp(config.clone()),
    )
    .expect("a target");
    assert!(target.clipboard(), "the clipboard is shared by default");
    assert_eq!(target.drive_folder(), None, "nothing is mapped by default");

    config.set_clipboard(false);
    config
        .set_drive_folder(Some(r"D:\Exchange"))
        .expect("a folder path");
    let target = crate::app::desktop::DesktopTarget::of_record(
        &shellune_core::ConnectionRecord::Rdp(config),
    )
    .expect("a target");
    assert!(!target.clipboard());
    assert_eq!(target.drive_folder(), Some(r"D:\Exchange"));

    let target = crate::app::desktop::DesktopTarget::of_record(&vnc_record_sharing("vnc", false))
        .expect("a target");
    assert!(!target.clipboard());
    assert_eq!(target.drive_folder(), None, "VNC has no drive to map");
}

#[gpui::test]
async fn the_rdp_form_saves_the_clipboard_switch_and_the_folder_and_vnc_has_only_the_switch(
    cx: &mut TestAppContext,
) {
    let dir = TempDir::new("desktop-sharing-form");
    let (view, cx) = hosts_view(cx, dir.store());
    cx.simulate_resize(size(px(1400.0), px(1300.0)));
    cx.run_until_parked();

    click(cx, "hosts.new");
    click(cx, "connection.protocol.rdp");
    assert!(cx.update(|_window, app| {
        view.read(app)
            .hosts_state()
            .protocol_draft()
            .is_some_and(|draft| draft.clipboard())
    }));
    type_into(cx, "connection.field.address", "10.0.0.9");
    click(cx, "connection.field.clipboard");
    type_into(cx, "connection.field.drive_folder", r"C:\Exchange");
    assert!(
        cx.debug_bounds("connection.drive_folder.note").is_some(),
        "the folder says what the remote side sees"
    );
    click(cx, "connection.save");

    let saved = cx.update(|_window, app| view.read(app).book().connections().to_vec());
    let rdp = saved
        .iter()
        .find_map(|record| match record {
            shellune_core::ConnectionRecord::Rdp(config) => Some(config.clone()),
            _ => None,
        })
        .expect("the RDP connection was saved");
    assert!(!rdp.clipboard(), "the switch was turned off and saved off");
    assert_eq!(rdp.drive_folder(), Some(r"C:\Exchange"));

    // Opening it again shows both choices as they were saved.
    let id = rdp.id();
    cx.update(|_window, cx| {
        view.update(cx, |view, cx| view.edit_connection_for_test(id, cx));
    });
    cx.run_until_parked();
    let draft = cx.update(|_window, app| view.read(app).hosts_state().protocol_draft().cloned());
    let draft = draft.expect("the form is open");
    assert!(!draft.clipboard());
    assert_eq!(
        draft.text(crate::app::hosts::ConnectionFormField::DriveFolder),
        r"C:\Exchange"
    );
    click(cx, "connection.cancel");

    // A VNC form has the switch and no folder.
    click(cx, "hosts.new");
    click(cx, "connection.protocol.vnc");
    redraw(cx);
    let fields = cx.update(|_window, app| {
        view.read(app)
            .hosts_state()
            .protocol_draft()
            .map(|draft| draft.fields().to_vec())
    });
    let fields = fields.expect("the VNC form is open");
    assert!(fields.contains(&crate::app::hosts::ConnectionFormField::Clipboard));
    assert!(!fields.contains(&crate::app::hosts::ConnectionFormField::DriveFolder));
    type_into(cx, "connection.field.address", "10.0.0.41");
    click(cx, "connection.field.clipboard");
    click(cx, "connection.save");
    let vnc = cx.update(|_window, app| {
        view.read(app)
            .book()
            .connections()
            .iter()
            .find_map(|record| match record {
                shellune_core::ConnectionRecord::Vnc(config) => Some(config.clone()),
                _ => None,
            })
    });
    assert!(
        !vnc.expect("the VNC connection was saved").clipboard(),
        "a VNC connection keeps its switch too"
    );
}

#[gpui::test]
async fn a_desktop_connection_names_each_step_before_the_picture(cx: &mut TestAppContext) {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let desktop = (1600u32, 900u32);
    let (link, _log) = ScriptedLink::new(vec![LinkEvent::State {
        state: LinkState::Connecting,
        failure: LinkFailure::None,
        detail: 0,
        reason: String::new(),
    }]);
    let feed = link.feed();
    let record = desktop_record("desk");
    let id = mount_scripted_desktop(&view, cx, &record, link);

    let step = |cx: &mut VisualTestContext| {
        cx.update(|_window, app| {
            let view = view.read(app);
            let pane = view
                .desktop_of(id)
                .expect("the surface is mounted")
                .read(app);
            (
                pane.stage(),
                view.workspace()
                    .session(id)
                    .map(|session| session.state().clone()),
            )
        })
    };

    let (stage, state) = step(cx);
    assert_eq!(
        stage,
        crate::app::view::DesktopStage::Connecting,
        "the first step is the connection itself"
    );
    assert_eq!(state, Some(SessionState::Connecting));
    assert!(
        cx.debug_bounds("desktop.status").is_some(),
        "the step is stated on screen"
    );

    // The server asks about its certificate.
    feed.feed(vec![LinkEvent::Certificate {
        request_id: 2,
        host: "rdp.example.com".to_owned(),
        subject: "CN=rdp".to_owned(),
        issuer: "CN=ca".to_owned(),
        fingerprint: "EE:FF".to_owned(),
        flags: 0,
    }]);
    pump_desktop(&view, cx, id);
    let (stage, state) = step(cx);
    assert_eq!(stage, crate::app::view::DesktopStage::VerifyingCertificate);
    assert_eq!(
        state,
        Some(SessionState::VerifyingHost),
        "the record says the host identity is being verified, not that it is connected"
    );
    assert!(cx.debug_bounds("desktop.certificate").is_some());

    // The user accepts it, and the sign-in is the step after that.
    let trust = bounds_of(cx, "desktop.certificate.trust").center();
    cx.simulate_click(trust, Modifiers::default());
    cx.run_until_parked();
    let (stage, state) = step(cx);
    assert_eq!(stage, crate::app::view::DesktopStage::Authenticating);
    assert_eq!(state, Some(SessionState::Authenticating));

    // The protocol accepts the session; the desktop itself is still being built.
    feed.feed(vec![LinkEvent::State {
        state: LinkState::Connected,
        failure: LinkFailure::None,
        detail: 0,
        reason: String::new(),
    }]);
    pump_desktop(&view, cx, id);
    let (stage, state) = step(cx);
    assert_eq!(stage, crate::app::view::DesktopStage::Establishing);
    assert_eq!(
        state,
        Some(SessionState::Authenticating),
        "a session with no picture is not called connected"
    );
    assert!(!cx.update(|_window, app| {
        view.read(app)
            .desktop_of(id)
            .expect("the surface is mounted")
            .read(app)
            .is_live()
    }));

    // The first frame is the moment it is live.
    feed.feed(vec![LinkEvent::Frame(solid(
        0,
        0,
        1600,
        900,
        desktop,
        [1, 1, 1, 255],
    ))]);
    pump_desktop(&view, cx, id);
    let (_stage, state) = step(cx);
    assert_eq!(state, Some(SessionState::Connected));

    // Every step has its own words, so the card cannot say the same thing twice.
    let english = Locale::English.strings();
    let words = [
        crate::app::view::DesktopStage::Connecting,
        crate::app::view::DesktopStage::VerifyingCertificate,
        crate::app::view::DesktopStage::Authenticating,
        crate::app::view::DesktopStage::Establishing,
    ]
    .map(|stage| stage.headline(english));
    let mut unique = words.to_vec();
    unique.sort_unstable();
    unique.dedup();
    assert_eq!(
        unique.len(),
        words.len(),
        "the steps are told apart: {words:?}"
    );
    assert_eq!(
        crate::app::view::DesktopStage::VerifyingCertificate.headline(english),
        "Waiting for the certificate decision"
    );
    assert_eq!(
        crate::app::view::DesktopStage::Authenticating.headline(Locale::Chinese.strings()),
        "正在认证"
    );
    assert!(
        !crate::app::view::DesktopStage::Establishing
            .headline(english)
            .is_empty(),
        "the last step has words of its own too"
    );
}

#[gpui::test]
async fn a_desktop_that_failed_while_signing_in_says_which_step_it_stopped_on(
    cx: &mut TestAppContext,
) {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let (link, _log) = ScriptedLink::new(vec![
        LinkEvent::Certificate {
            request_id: 5,
            host: "rdp.example.com".to_owned(),
            subject: "CN=rdp".to_owned(),
            issuer: "CN=ca".to_owned(),
            fingerprint: "11:22".to_owned(),
            flags: 0,
        },
        LinkEvent::State {
            state: LinkState::Failed(LinkFailure::Authentication),
            failure: LinkFailure::Authentication,
            detail: 0,
            reason: "the server rejected the logon".to_owned(),
        },
    ]);
    let record = desktop_record("desk");
    let id = mount_scripted_desktop(&view, cx, &record, link);
    let (stage, state, reason) = cx.update(|_window, app| {
        let view = view.read(app);
        let pane = view
            .desktop_of(id)
            .expect("the surface is mounted")
            .read(app);
        (
            pane.failed_stage(),
            view.workspace()
                .session(id)
                .map(|session| session.state().clone()),
            view.workspace()
                .status(id)
                .and_then(|status| status.diagnostic().map(str::to_owned)),
        )
    });
    assert_eq!(
        stage,
        Some(crate::app::view::DesktopStage::VerifyingCertificate),
        "the run stopped on the certificate step, so that is the step it names"
    );
    assert_eq!(
        state,
        Some(SessionState::Failed(SessionFailure::AuthenticationFailed))
    );
    assert!(
        reason
            .as_ref()
            .is_some_and(|reason| reason.contains("credentials")),
        "the reason is stated beside the step: {reason:?}"
    );
    assert!(
        cx.debug_bounds("desktop.status").is_some(),
        "the ended session keeps its card, and the card names the step"
    );
}

// ---------------------------------------------------------------- serial (R17, R21)

/// A saved serial connection for the tests.
fn serial_record(name: &str, device: &str) -> shellune_core::ConnectionRecord {
    shellune_core::ConnectionRecord::Serial(
        shellune_core::SerialConfig::new(name, device).expect("a valid serial record"),
    )
}

/// One end of an in-memory serial pair, and the session a pane drives over it.
///
/// The session is the real one - reader thread, writer thread, bounded queue, close -
/// over the in-memory port this crate builds for tests. This machine has no serial
/// device and no virtual pair, so a fake is the only way to move bytes; nothing here is
/// evidence about a UART, a cable or a driver, and no assertion below is written as if
/// it were.
fn scripted_serial() -> (SerialLink, Arc<FakePort>, Arc<FakePort>) {
    let (device, peer) = shellune_serial::testing::fake_pair();
    let session = shellune_serial::testing::session_over(
        Arc::clone(&device),
        shellune_serial::SerialConfig::default(),
    );
    (SerialLink::holding(session), device, peer)
}

/// Mounts a serial session on a scripted link, through the path the application uses.
fn mount_scripted_serial(
    view: &Entity<ShelluneView>,
    cx: &mut VisualTestContext,
    name: &str,
    device: &str,
    local_echo: bool,
    link: SerialLink,
) -> SessionId {
    let record = serial_record(name, device);
    let id = cx.update(|_window, cx| {
        view.update(cx, |view, cx| {
            view.attach_scripted_serial_for_test(
                &record,
                link,
                device,
                "115200 8N1, none flow control",
                local_echo,
                cx,
            )
        })
    });
    pump_serial(view, cx, id);
    id
}

/// Polls the pane until what was pushed has really arrived.
///
/// The session reads and writes on its own threads, so a byte handed to the device and
/// a byte written to it are both asynchronous: a single poll would assert on the state
/// of a race rather than on the rule.
fn pump_serial_until(
    view: &Entity<ShelluneView>,
    cx: &mut VisualTestContext,
    id: SessionId,
    mut done: impl FnMut(&TerminalPane) -> bool,
) {
    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(5);
    loop {
        pump_serial(view, cx, id);
        let reached = cx.update(|_window, app| {
            view.read(app)
                .pane_of(id)
                .is_some_and(|pane| done(pane.read(app)))
        });
        if reached || std::time::Instant::now() >= deadline {
            return;
        }
        std::thread::sleep(std::time::Duration::from_millis(5));
    }
}

/// Waits for something the session does on its writer thread.
fn wait_for(mut done: impl FnMut() -> bool) -> bool {
    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(5);
    while std::time::Instant::now() < deadline {
        if done() {
            return true;
        }
        std::thread::sleep(std::time::Duration::from_millis(2));
    }
    done()
}

/// Applies whatever the device has sent since the last poll, the way the poll does.
fn pump_serial(view: &Entity<ShelluneView>, cx: &mut VisualTestContext, id: SessionId) {
    cx.update(|_window, cx| {
        view.update(cx, |view, cx| {
            if let Some(pane) = view.pane_of(id).cloned() {
                pane.update(cx, |pane, cx| {
                    pane.pump_once(cx);
                });
            }
        });
    });
    cx.run_until_parked();
}

#[gpui::test]
async fn serial_bytes_reach_the_terminal_grid_and_scroll_back(cx: &mut TestAppContext) {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let (link, device, _peer) = scripted_serial();
    let id = mount_scripted_serial(&view, cx, "console", "COM3", false, link);
    // The device sends more than one screen, so scrollback exists at all: what is
    // measured is the same grid, selection and history a local shell uses. The line
    // count is well past any window size, so the oldest rows really did scroll off
    // instead of fitting on the first screen.
    let mut sent = Vec::new();
    for line in 0..400 {
        sent.extend_from_slice(format!("line {line}\r\n").as_bytes());
    }
    device.push_from_device(&sent);
    pump_serial_until(&view, cx, id, |pane| {
        pane.visible_text()
            .iter()
            .any(|row| row.contains("line 399"))
    });
    let (text, history, live) = cx.update(|_window, app| {
        let pane = view.read(app).pane_of(id).expect("the pane is mounted");
        let pane = pane.read(app);
        (
            pane.visible_text(),
            pane.history_len(),
            pane.state().accepts_input(),
        )
    });
    assert!(live, "the session is live while the device is open");
    assert!(
        text.iter().any(|row| row.contains("line 399")),
        "the last line the device sent is on the grid: {text:?}"
    );
    assert!(
        history > 0,
        "the lines that scrolled off are kept, so the view can scroll back"
    );
}

#[gpui::test]
async fn the_newline_choice_changes_what_is_sent_and_never_what_arrives(cx: &mut TestAppContext) {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let (link, device, _peer) = scripted_serial();
    let id = mount_scripted_serial(&view, cx, "console", "COM3", false, link);

    // As typed: the bytes go out exactly as the terminal encoded them.
    cx.update(|_window, cx| {
        view.update(cx, |view, cx| {
            let pane = view.pane_of(id).expect("the pane is mounted").clone();
            pane.update(cx, |pane, cx| pane.type_text("at\n", cx));
        });
    });
    assert!(
        wait_for(|| device.written() == b"at\n"),
        "nothing is rewritten by default: {:?}",
        device.written()
    );

    // CRLF: every break the user sends becomes the pair the device expects.
    cx.update(|_window, cx| {
        view.update(cx, |view, cx| {
            let pane = view.pane_of(id).expect("the pane is mounted").clone();
            pane.update(cx, |pane, cx| {
                pane.set_serial_format(
                    crate::app::serial::NewlineFormat::CarriageReturnLineFeed,
                    cx,
                );
                pane.type_text("crlf\r\n", cx);
            });
        });
    });
    assert!(
        wait_for(|| device.written() == b"at\ncrlf\r\n"),
        "a pair is one line break and is rewritten once: {:?}",
        device.written()
    );

    // What the device returns is never rewritten, whichever ending is chosen.
    device.push_from_device(b"device\nsaid\r\nso\r\n");
    pump_serial_until(&view, cx, id, |pane| {
        pane.visible_text().iter().any(|row| row.contains("device"))
    });
    let text = cx.update(|_window, app| {
        view.read(app)
            .pane_of(id)
            .expect("the pane is mounted")
            .read(app)
            .visible_text()
    });
    assert!(
        text.iter().any(|row| row.contains("device")),
        "the bytes the device sent reach the grid: {text:?}"
    );
    assert_eq!(
        device.written(),
        b"at\ncrlf\r\n",
        "nothing the device sent was echoed back out"
    );
}

#[gpui::test]
async fn the_local_echo_shows_what_was_typed_and_device_bytes_stay_single(cx: &mut TestAppContext) {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let (link, device, _peer) = scripted_serial();
    let id = mount_scripted_serial(&view, cx, "console", "COM3", true, link);
    cx.update(|_window, cx| {
        view.update(cx, |view, cx| {
            let pane = view.pane_of(id).expect("the pane is mounted").clone();
            pane.update(cx, |pane, cx| pane.type_text("typed", cx));
        });
    });
    cx.run_until_parked();
    let text = cx.update(|_window, app| {
        view.read(app)
            .pane_of(id)
            .expect("the pane is mounted")
            .read(app)
            .visible_text()
    });
    assert!(
        text.iter().any(|row| row.contains("typed")),
        "the echo shows what was typed while the device says nothing: {text:?}"
    );
    assert!(
        wait_for(|| device.written() == b"typed"),
        "and it was sent once: {:?}",
        device.written()
    );

    // A device that answers is not echoed: only the send path draws the local echo, so
    // a byte from the device appears once and never comes back out on the wire.
    device.push_from_device(b"answer");
    pump_serial_until(&view, cx, id, |pane| {
        pane.visible_text().iter().any(|row| row.contains("answer"))
    });
    let text = cx.update(|_window, app| {
        view.read(app)
            .pane_of(id)
            .expect("the pane is mounted")
            .read(app)
            .visible_text()
    });
    let line = text
        .iter()
        .find(|row| row.contains("answer"))
        .expect("the answer is shown");
    assert_eq!(
        line.matches("answer").count(),
        1,
        "the device text is drawn once, not echoed a second time: {line:?}"
    );
    assert_eq!(
        device.written(),
        b"typed",
        "what the device sent is never written back to it"
    );
}

#[gpui::test]
async fn a_device_that_will_not_open_keeps_its_tab_and_states_why(cx: &mut TestAppContext) {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    // A port name no machine has. Opening it really goes through the system API, so the
    // reason is the one the system reports - not a sentence a test put there.
    let record = serial_record("console", "COM999");
    let id = cx.update(|_window, cx| {
        view.update(cx, |view, cx| {
            view.start_serial_with_record_for_test(&record, cx)
        })
    });
    cx.run_until_parked();
    let (state, note, pane_device) = cx.update(|_window, app| {
        let view = view.read(app);
        let pane = view.pane_of(id).expect("the pane is kept");
        let pane = pane.read(app);
        (
            view.workspace()
                .session(id)
                .map(|session| session.state().clone()),
            pane.serial_note().map(str::to_owned),
            pane.serial().map(|serial| serial.device().to_owned()),
        )
    });
    assert!(
        matches!(state, Some(SessionState::Failed(_))),
        "a device that never opened is a failed session, never a live one: {state:?}"
    );
    let note = note.expect("the reason is stated on the pane");
    assert!(
        note.contains("COM999"),
        "the sentence names the device it is about: {note}"
    );
    assert!(
        note.contains("not found") || note.contains("not exist"),
        "and it is the cause the system allowed: {note}"
    );
    assert!(
        note.contains("Refresh the port list"),
        "with the next step the cause points at: {note}"
    );
    assert_eq!(
        pane_device.as_deref(),
        Some("COM999"),
        "the pane is about the device the record names, not a similar one"
    );
}

#[gpui::test]
async fn the_port_list_tells_a_failed_read_from_an_empty_machine_and_a_missing_device(
    cx: &mut TestAppContext,
) {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let (link, _device, _peer) = scripted_serial();
    let id = mount_scripted_serial(&view, cx, "console", "COM3", false, link);
    let wanted_missing = Locale::English.strings().serial_ports_missing;
    let lines = cx.update(|_window, app| {
        let view = view.read(app);
        let pane = view.pane_of(id).expect("the pane is mounted").clone();
        let mut lines = Vec::new();
        for scan in [
            PortScan::Failed("the list could not be read".to_owned()),
            PortScan::Ready(Vec::new()),
            PortScan::Ready(vec![shellune_serial::PortInfo::sample(
                "COM30", "COM30", None,
            )]),
        ] {
            pane.update(app, |pane, cx| pane.show_serial_ports(scan, cx));
            let serial = pane.read(app).serial().expect("a serial pane");
            lines.push(crate::app::terminal::ports_line(serial, Locale::English));
        }
        lines
    });
    let strings = Locale::English.strings();
    assert!(
        lines[0].contains(strings.serial_ports_failed),
        "a list that could not be read says so: {lines:?}"
    );
    assert!(
        lines[1].contains(strings.serial_ports_empty)
            && lines[1].contains(strings.serial_ports_hint),
        "an answer with no ports says that, and what to do: {lines:?}"
    );
    assert!(
        lines[2].contains("COM30") && lines[2].contains(wanted_missing),
        "a similar name is listed as present but not as the saved device: {lines:?}"
    );
    assert_ne!(
        lines[0], lines[1],
        "a failed read and an empty machine are two different sentences"
    );
}

#[gpui::test]
async fn a_similar_port_name_is_never_taken_for_the_saved_device(cx: &mut TestAppContext) {
    let _ = cx;
    let attached = PortScan::Ready(vec![shellune_serial::PortInfo::sample(
        "COM30", "COM30", None,
    )]);
    assert_eq!(
        DeviceChoice::of(&attached, "COM3"),
        DeviceChoice::Missing,
        "a COM30 that is plugged in does not stand in for a COM3 that is not"
    );
    assert_eq!(
        DeviceChoice::of(&attached, "com30"),
        DeviceChoice::Attached,
        "the same port written in another case is still the same port"
    );
}

#[gpui::test]
async fn closing_a_serial_session_releases_the_port_and_leaves_the_other_one_alone(
    cx: &mut TestAppContext,
) {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let (first, first_device, _first_peer) = scripted_serial();
    let (second, second_device, _second_peer) = scripted_serial();
    let first_id = mount_scripted_serial(&view, cx, "one", "COM1", false, first);
    let second_id = mount_scripted_serial(&view, cx, "two", "COM2", false, second);
    cx.update(|_window, cx| {
        view.update(cx, |view, cx| view.close_session(first_id, cx));
    });
    cx.run_until_parked();
    assert!(
        first_device.is_released(),
        "the port of the closed session is released"
    );
    let (state, open) = cx.update(|_window, app| {
        let view = view.read(app);
        (
            view.workspace()
                .session(first_id)
                .map(|session| session.state().clone()),
            view.open_sessions().contains(&second_id),
        )
    });
    assert_eq!(
        state,
        Some(SessionState::Closed),
        "the closed session says so"
    );
    assert!(open, "the other session is still open");

    // The session that was left alone still sends: closing one port does not touch the
    // worker of another.
    cx.update(|_window, cx| {
        view.update(cx, |view, cx| {
            let pane = view
                .pane_of(second_id)
                .expect("the pane is mounted")
                .clone();
            pane.update(cx, |pane, cx| pane.type_text("still here", cx));
        });
    });
    let typed = cx.update(|_window, app| {
        let view = view.read(app);
        let pane = view
            .pane_of(second_id)
            .map(|pane| pane.read(app).sent().to_vec());
        let state = view
            .workspace()
            .session(second_id)
            .map(|session| session.state().clone());
        let note = view
            .pane_of(second_id)
            .and_then(|pane| pane.read(app).serial_note().map(str::to_owned));
        (pane, state, note)
    });
    assert!(
        wait_for(|| second_device.written() == b"still here"),
        "the surviving session still sends: {:?} (typed {:?})",
        second_device.written(),
        typed
    );
}

/// One in-memory port driven as a real session, with the bounds a test needs.
///
/// The session is the crate's own - reader thread, writer thread, bounded queue and
/// close - over the in-memory FakePort; this machine has no serial device and no virtual
/// pair, so a fake is the only way to move bytes, and nothing here is evidence about a
/// UART, a driver or a cable.
fn scripted_serial_port(
    device: &str,
    spec: shellune_serial::testing::FakeSpec,
    close_timeout: std::time::Duration,
) -> (SerialLink, Arc<FakePort>) {
    let port = shellune_serial::testing::fake(device, spec);
    let limits = shellune_serial::SessionLimits {
        close_timeout,
        ..shellune_serial::SessionLimits::default()
    };
    let session = shellune_serial::testing::session_over_with(
        Arc::clone(&port),
        shellune_serial::SerialConfig::default(),
        limits,
    );
    (SerialLink::holding(session), port)
}

/// A link whose device reports a read failure, as an unplugged adapter does.
fn unplugged_serial(device: &str) -> (SerialLink, Arc<FakePort>) {
    let spec = shellune_serial::testing::FakeSpec::new().failing_reads(
        shellune_serial::SerialError::new(shellune_serial::SerialCause::Disconnected)
            .at(device)
            .with_detail("the device was removed"),
    );
    scripted_serial_port(device, spec, std::time::Duration::from_secs(2))
}

#[gpui::test]
async fn a_text_commit_on_a_serial_pane_echoes_once_and_rewrites_only_its_own_break(
    cx: &mut TestAppContext,
) {
    use gpui::EntityInputHandler;

    // A window and a device that says nothing at all: everything that appears on the
    // grid below came from the user's own typing, which is the blind-typing case R21 is
    // about.
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let (link, device, _peer) = scripted_serial();
    let id = mount_scripted_serial(&view, cx, "console", "COM3", true, link);

    // This is the path a keyboard really drives: WM_CHAR reaches gpui as a text commit,
    // and a commit calls the input handler, not the key encoder. Printable characters,
    // spaces and committed Chinese input never reach the key path at all, so a pane that
    // only echoed in the key path showed nothing while a user typed.
    let commit = |cx: &mut VisualTestContext, text: &str| {
        cx.update(|window, app| {
            let pane = view
                .read(app)
                .pane_of(id)
                .expect("the pane is mounted")
                .clone();
            pane.update(app, |pane, cx| {
                pane.replace_text_in_range(None, text, window, cx);
            });
        });
        cx.run_until_parked();
    };

    commit(cx, "hello");
    let shown = cx.update(|_window, app| {
        view.read(app)
            .pane_of(id)
            .expect("the pane is mounted")
            .read(app)
            .visible_text()
    });
    assert!(
        shown.iter().any(|row| row.contains("hello")),
        "a committed text is echoed into the grid, so typing is not blind: {shown:?}"
    );
    assert!(
        wait_for(|| device.written() == b"hello"),
        "and it reached the device once, in the order it was typed: {:?}",
        device.written()
    );

    // A break that arrives through the text path obeys the chosen ending, exactly once:
    // one line feed on the wire becomes one CR LF, not two.
    cx.update(|_window, cx| {
        view.update(cx, |view, cx| {
            let pane = view.pane_of(id).expect("the pane is mounted").clone();
            pane.update(cx, |pane, cx| {
                pane.set_serial_format(
                    crate::app::serial::NewlineFormat::CarriageReturnLineFeed,
                    cx,
                );
            });
        });
    });
    commit(cx, "a\nb");
    assert!(
        wait_for(|| device.written() == b"helloa\r\nb"),
        "the commit's line feed was rewritten once, and nothing else was: {:?}",
        device.written()
    );
    let rows = cx.update(|_window, app| {
        view.read(app)
            .pane_of(id)
            .expect("the pane is mounted")
            .read(app)
            .visible_text()
    });
    // The caret was still on the row the previous echo left it on, so the first line of
    // the commit continues that row and the second one starts the next: one break, one
    // row - a second rewriting would leave an empty row between them.
    let a = rows
        .iter()
        .position(|row| row.trim_end() == "helloa")
        .unwrap_or_else(|| panic!("the echoed lines are on the grid: {rows:?}"));
    assert_eq!(
        rows.get(a + 1).map(|row| row.trim_end()),
        Some("b"),
        "the echo of one break moves the caret one row down, not two: {rows:?}"
    );

    // What the device sends is drawn as it arrived: never echoed a second time, and
    // never rewritten by the newline choice - the transcript has to agree with the wire.
    device.push_from_device(b"from-device\r\n");
    pump_serial_until(&view, cx, id, |pane| {
        pane.visible_text()
            .iter()
            .any(|row| row.contains("from-device"))
    });
    let text = cx.update(|_window, app| {
        view.read(app)
            .pane_of(id)
            .expect("the pane is mounted")
            .read(app)
            .visible_text()
    });
    let line = text
        .iter()
        .find(|row| row.contains("from-device"))
        .expect("the device text is drawn");
    assert_eq!(
        line.matches("from-device").count(),
        1,
        "the device's own text is drawn once, not echoed: {line:?}"
    );
    assert_eq!(
        device.written(),
        b"helloa\r\nb",
        "bytes the device sent were never written back to it: {:?}",
        device.written()
    );
}

#[gpui::test]
async fn serial_queue_refusal_does_not_echo_unsent_text(cx: &mut TestAppContext) {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let port = shellune_serial::testing::fake(
        "COM3",
        shellune_serial::testing::FakeSpec::new().holding_writes(),
    );
    let session = shellune_serial::testing::session_over_with(
        port,
        shellune_serial::SerialConfig::default(),
        shellune_serial::SessionLimits {
            queued_bytes: 4,
            ..Default::default()
        },
    );
    let id = mount_scripted_serial(
        &view,
        cx,
        "console",
        "COM3",
        true,
        SerialLink::holding(session),
    );
    cx.update(|_window, app| {
        let pane = view.read(app).pane_of(id).unwrap().clone();
        pane.update(app, |pane, cx| {
            pane.type_text("sent", cx);
            pane.type_text("refused", cx);
            let shown = pane.visible_text().join("\n");
            assert!(shown.contains("sent"));
            assert!(!shown.contains("refused"));
            assert!(pane.state().accepts_input());
        });
    });
}

#[gpui::test]
async fn a_closed_serial_tab_still_says_which_frames_never_left(cx: &mut TestAppContext) {
    // A driver that takes the first frame and then holds it: the second frame is still in
    // the queue when the tab closes, which is the case a person has to be told about.
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let (link, device) = scripted_serial_port(
        "COM3",
        shellune_serial::testing::FakeSpec::new().holding_writes(),
        std::time::Duration::from_secs(2),
    );
    let id = mount_scripted_serial(&view, cx, "console", "COM3", false, link);
    cx.update(|_window, cx| {
        view.update(cx, |view, cx| {
            let pane = view.pane_of(id).expect("the pane is mounted").clone();
            pane.update(cx, |pane, cx| {
                pane.type_text("first", cx);
                pane.type_text("second", cx);
            });
        });
    });
    // Let the writer take the first frame, so the second is really queued at the close.
    std::thread::sleep(std::time::Duration::from_millis(60));
    cx.update(|_window, cx| {
        view.update(cx, |view, cx| view.close_session(id, cx));
    });
    cx.run_until_parked();

    let (gone, titles, entries, queued) = cx.update(|_window, app| {
        let view = view.read(app);
        (
            pane_gone(app, view, id),
            view.toast_titles(),
            view.toast_entries(),
            view.workspace()
                .session(id)
                .map(|session| session.title().to_owned()),
        )
    });
    assert!(gone, "the tab is closed");
    assert!(
        queued.is_some(),
        "the session record survives the pane, so the tab it named is accounted for"
    );
    let note = titles
        .iter()
        .find(|title| title.contains("never sent"))
        .unwrap_or_else(|| panic!("the corner says what was left behind: {titles:?}"));
    let count: usize = note
        .chars()
        .take_while(char::is_ascii_digit)
        .collect::<String>()
        .parse()
        .expect("the sentence starts with how many frames were left");
    assert!(
        count >= 1,
        "the number of frames that never left is stated: {note}"
    );
    assert!(
        note.contains("bytes)"),
        "and so is how much of them there was: {note}"
    );
    assert!(
        entries
            .iter()
            .any(|(tone, title)| *tone == Tone::Warning && title.contains("never sent")),
        "a close that lost bytes is not reported as a success: {entries:?}"
    );
    assert!(
        !titles.iter().any(|title| title.contains("still held")),
        "a port that was really released is not called held: {titles:?}"
    );
    assert!(
        device.written().is_empty(),
        "the frame the driver was inside never reached the wire either: {:?}",
        device.written()
    );
}

#[gpui::test]
async fn a_close_the_driver_never_answers_is_reported_after_the_tab_is_gone(
    cx: &mut TestAppContext,
) {
    // A driver that ignores the cancellation request: the close waits, gives up and says
    // the port is still held. The wait is shortened so the test does not sit for two
    // seconds; the sequence is the application's.
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let (link, device) = scripted_serial_port(
        "COM4",
        shellune_serial::testing::FakeSpec::new().ignoring_interrupt(),
        std::time::Duration::from_millis(60),
    );
    let id = mount_scripted_serial(&view, cx, "console", "COM4", false, link);
    cx.update(|_window, cx| {
        view.update(cx, |view, cx| view.close_session(id, cx));
    });
    cx.run_until_parked();
    let strings = Locale::English.strings();
    let titles = cx.update(|_window, app| {
        let view = view.read(app);
        assert!(
            pane_gone(app, view, id),
            "the tab keeps closing even when the port does not"
        );
        view.toast_titles()
    });
    let note = titles
        .iter()
        .find(|title| title.contains(strings.serial_still_held))
        .unwrap_or_else(|| panic!("the corner says the port is still held: {titles:?}"));
    assert!(
        note.contains("did not stop within"),
        "the sentence says what the driver did instead of stopping: {note}"
    );
    assert!(
        !device.is_released(),
        "and the port really was still held, so the sentence is true"
    );
    // Let the blocked read finish so the thread does not outlive the test.
    device.release_driver();
}

#[gpui::test]
async fn a_serial_session_that_lost_its_device_stops_driving_it(cx: &mut TestAppContext) {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let (link, device) = unplugged_serial("COM3");
    let id = mount_scripted_serial(&view, cx, "console", "COM3", false, link);

    // The device goes away: the reader reports it and the session ends. The tab stays -
    // it names the device and the reason - but the line must stop being driven.
    pump_serial_until(&view, cx, id, |pane| !pane.state().accepts_input());
    cx.run_until_parked();
    let state = session_state(cx, &view, id);
    assert!(
        matches!(state, Some(SessionState::Disconnected(_))),
        "the session states the loss instead of looking live: {state:?}"
    );
    let (holds, still_open, note, titles) = cx.update(|_window, app| {
        let view = view.read(app);
        let pane = view.pane_of(id).expect("the pane is still there");
        let pane = pane.read(app);
        (
            pane.holds_source(),
            view.open_sessions().contains(&id),
            pane.serial_note().map(str::to_owned),
            view.toast_titles(),
        )
    });
    assert!(
        !holds,
        "the pane let go of the device when the session ended, so the writer thread and the send queue do not outlive it"
    );
    assert!(
        still_open,
        "the tab stays: it is what tells the user which device went away"
    );
    assert!(
        device.is_released(),
        "the port is back with the system, so the device can be opened again"
    );
    assert!(
        note.is_none()
            || titles
                .iter()
                .any(|title| note.as_deref() == Some(title.as_str())),
        "a note about the close is shown in the corner as well as on the strip: {note:?} / {titles:?}"
    );
    // Running the release twice is harmless: the session is over either way.
    let again = cx.update(|_window, app| {
        let pane = view
            .read(app)
            .pane_of(id)
            .expect("the pane is there")
            .clone();
        pane.update(app, |pane, cx| pane.release_serial(cx))
    });
    assert!(again.is_none(), "a second release has nothing left to say");
}

/// Whether a session has no pane any more, for a test.
fn pane_gone(_app: &gpui::App, view: &ShelluneView, id: SessionId) -> bool {
    view.pane_of(id).is_none() && !view.open_sessions().contains(&id)
}

#[gpui::test]
async fn a_serial_session_reconnects_in_its_own_tab_without_replaying_the_old_queue(
    cx: &mut TestAppContext,
) {
    let dir = TempDir::new("serial-reconnect");
    // The record is really saved, because the reconnect reads it back from the book the
    // way the application does: a session that is reopened is the one the user saved.
    let record = serial_record("console", "COM3");
    let mut book = HostBook::new();
    book.insert_connection(record.clone())
        .expect("the serial record is saved");
    let store = dir.store();
    store.save(&book).expect("the book saves");
    let (view, cx) = cx
        .add_window_view(move |_window, cx| ShelluneView::with_store(cx, Workspace::new(), store));
    cx.run_until_parked();

    let (old_link, old_device) = unplugged_serial("COM3");
    let id = cx.update(|_window, cx| {
        view.update(cx, |view, cx| {
            view.attach_scripted_serial_for_test(
                &record,
                old_link,
                "COM3",
                "115200 8N1, none flow control",
                false,
                cx,
            )
        })
    });
    cx.run_until_parked();
    // The device goes away, which is what the reconnect entry answers.
    pump_serial_until(&view, cx, id, |pane| !pane.state().accepts_input());
    cx.run_until_parked();
    assert!(
        matches!(
            session_state(cx, &view, id),
            Some(SessionState::Disconnected(_))
        ),
        "the session ended before it is reopened"
    );
    let (old_pane, old_tag, name, kind, tabs) = cx.update(|_window, app| {
        let view = view.read(app);
        let pane = view.pane_of(id).expect("the pane is there").clone();
        let session = view.workspace().session(id).expect("the session is listed");
        (
            pane.clone(),
            pane.read(app).tag(),
            session.title().to_owned(),
            session.kind().clone(),
            view.open_sessions(),
        )
    });
    assert_eq!(tabs, vec![id], "one tab was open before the reconnect");

    // The device the record names is the in-memory pair here; the port of the previous
    // attempt is gone, and the queue it still held went with it.
    let (new_link, new_device, _new_peer) = scripted_serial();
    cx.update(|_window, cx| {
        view.update(cx, |view, _cx| {
            view.queue_scripted_serial_for_test("COM3", new_link);
        });
    });
    cx.update(|_window, cx| {
        view.update(cx, |view, cx| view.reconnect_session(id, cx));
    });
    cx.run_until_parked();

    let (new_pane, state, generation, device, tabs, kind_after, name_after) =
        cx.update(|_window, app| {
            let view = view.read(app);
            let pane = view
                .pane_of(id)
                .expect("the reconnected pane is there")
                .clone();
            let session = view.workspace().session(id).expect("the session is listed");
            let device = pane
                .read(app)
                .serial()
                .map(|serial| serial.device().to_owned());
            (
                pane.clone(),
                session.state().clone(),
                session.generation(),
                device,
                view.open_sessions(),
                session.kind().clone(),
                session.title().to_owned(),
            )
        });
    assert_ne!(
        new_pane.entity_id(),
        old_pane.entity_id(),
        "a reconnect is a new pane, not the old one restarted"
    );
    assert_eq!(tabs, vec![id], "the tab, its identity and its place stay");
    assert_eq!(
        (&kind_after, name_after.as_str()),
        (&kind, name.as_str()),
        "the session is still the same serial connection, named the same"
    );
    assert_eq!(
        state,
        SessionState::Connected,
        "the new attempt really opened a device"
    );
    assert_eq!(
        generation, 1,
        "the reconnect is another generation, so a late event can be told apart"
    );
    assert_eq!(
        device.as_deref(),
        Some("COM3"),
        "the device is the one the record names, never a similar port that happens to be attached"
    );
    assert!(
        old_device.written().is_empty(),
        "the port of the previous attempt received nothing that could be replayed: {:?}",
        old_device.written()
    );
    assert!(
        new_device.written().is_empty()
            && cx.update(|_window, app| new_pane.read(app).sent().is_empty()),
        "nothing typed into the lost session is sent again: {:?}",
        new_device.written()
    );

    // An event that still carries the previous generation is refused instead of being
    // drawn into the terminal that replaced it.
    let accepted = cx.update(|_window, app| {
        new_pane.update(app, |pane, cx| {
            pane.adopt_events(
                old_tag,
                vec![SourceEvent::Data(b"stale-from-the-old-port\r\n".to_vec())],
                cx,
            )
        })
    });
    assert!(
        !accepted,
        "an event of the previous attempt must be refused"
    );
    let screen = cx.update(|_window, app| new_pane.read(app).visible_text().join("\n"));
    assert!(
        !screen.contains("stale-from-the-old-port"),
        "the old port's output reached the new terminal: {screen:?}"
    );

    // The reconnected device really is the one driving the tab.
    new_device.push_from_device(b"alive\r\n");
    pump_serial_until(&view, cx, id, |pane| {
        pane.visible_text().iter().any(|row| row.contains("alive"))
    });
    let screen = cx.update(|_window, app| new_pane.read(app).visible_text().join("\n"));
    assert!(
        screen.contains("alive"),
        "the reconnected device reaches the tab: {screen:?}"
    );
}

// ---------------------------------------------------------------------------
// Following the shell's directory (R15)
// ---------------------------------------------------------------------------

/// One OSC 7 report, as a shell with directory reporting writes it.
fn directory_report(path: &str) -> Vec<u8> {
    format!("\u{1b}]7;file://web{path}\u{7}").into_bytes()
}

/// Opens the file view of one session with a scripted connection.
fn open_files_for(
    cx: &mut VisualTestContext,
    view: &Entity<ShelluneView>,
    id: SessionId,
    answers: &FileAnswers,
) {
    cx.update(|_window, app| {
        view.update(app, |view, cx| {
            view.attach_files_for_test(
                id,
                "web",
                "deploy@10.0.0.5:22",
                Box::new(answers.clone()),
                cx,
            );
        });
    });
    cx.run_until_parked();
    click(cx, "session.files");
}

/// The remote path one session's file view shows.
fn remote_path(
    cx: &mut VisualTestContext,
    view: &Entity<ShelluneView>,
    id: SessionId,
) -> Option<String> {
    cx.update(|_window, app| {
        view.read(app)
            .files_browser(id)
            .and_then(|browser| browser.path().map(str::to_owned))
    })
}

#[gpui::test]
async fn the_file_view_follows_the_directory_the_shell_reports(cx: &mut TestAppContext) {
    let (view, cx) = remote_view(cx);
    let id = live_remote(cx, &view);
    let answers = FileAnswers::accepting();
    open_files_for(cx, &view, id, &answers);
    answers.reply(
        1,
        "/home/deploy",
        &[("docs", shellune_core::FileKind::Directory)],
    );
    pump_files(cx, &view);
    assert_eq!(remote_path(cx, &view, id).as_deref(), Some("/home/deploy"));
    assert_eq!(
        cx.update(|_window, app| view.read(app).files_follow_note(id)),
        Some(crate::app::files::FollowNote::NoReport),
        "following waits for a report instead of pretending the login directory was one"
    );

    // The user runs cd /var/log, and the shell says so with OSC 7.
    feed_session(cx, &view, id, &directory_report("/var/log"));
    let request = match answers.requests().last().cloned() {
        Some(shellune_core::BrowseRequest::List { path, request }) => {
            assert_eq!(path, "/var/log", "the reported directory is listed");
            request
        }
        other => panic!("following asks for the reported directory, got {other:?}"),
    };
    answers.reply(
        request,
        "/var/log",
        &[("syslog", shellune_core::FileKind::File)],
    );
    pump_files(cx, &view);
    assert_eq!(remote_path(cx, &view, id).as_deref(), Some("/var/log"));
    assert_eq!(
        cx.update(|_window, app| view.read(app).files_follow_note(id)),
        Some(crate::app::files::FollowNote::Following {
            path: "/var/log".to_owned()
        })
    );
    assert!(
        cx.debug_bounds("files.follow").is_some(),
        "the switch that says the view follows is on screen"
    );
    // R4: the switch is a small icon in the column's header, right after its refresh,
    // and nothing about following takes a row of its own under the path.
    let follow = bounds_of(cx, "files.follow");
    let refresh = bounds_of(cx, "files.refresh");
    let header = bounds_of(cx, "files.header");
    assert!(
        (follow.top() - refresh.top()).abs() <= px(0.5)
            && follow.left() >= refresh.right() - px(0.5)
            && follow.left() - refresh.right() <= px(8.0),
        "the switch sits beside the refresh: follow {follow:?}, refresh {refresh:?}"
    );
    assert!(
        follow.top() >= header.top() - px(0.5) && follow.bottom() <= header.bottom() + px(0.5),
        "the switch is part of the column's header: follow {follow:?}, header {header:?}"
    );
    assert!(
        follow.size.width <= px(32.0) && follow.size.height <= px(32.0),
        "the switch is an icon, not a labelled segment: {follow:?}"
    );
    assert!(
        cx.debug_bounds("files.follow.row").is_none()
            && cx.debug_bounds("files.follow.note").is_none(),
        "no follow row and no note sit under the path"
    );
    assert_eq!(
        cx.update(|_window, app| view.read(app).files_follow_tooltip_for_test(id)),
        crate::app::copy::Locale::English.strings().files_follow_on,
        "while it follows, the tooltip says only that it is on"
    );

    // The report was a report: it is not part of what the terminal shows.
    let screen = cx.update(|_window, app| {
        view.read(app)
            .pane_of(id)
            .map(|pane| pane.read(app).visible_text().join("\n"))
            .unwrap_or_default()
    });
    assert!(
        !screen.contains("file://") && !screen.contains("7;"),
        "the sequence is not drawn as text: {screen:?}"
    );
}

#[gpui::test]
async fn a_step_up_the_root_cannot_take_keeps_following_on(cx: &mut TestAppContext) {
    // R15: only a directory the user really moved to is browsing by hand. At the root
    // there is no parent, so the switch must not quietly turn itself off.
    let (view, cx) = remote_view(cx);
    let id = live_remote(cx, &view);
    let files = FileAnswers::accepting();
    let channel = files.clone();
    cx.update(|_window, app| {
        view.update(app, |view, cx| {
            view.attach_files_for_test(id, "web", "deploy@10.0.0.5:22", Box::new(channel), cx);
        });
    });
    cx.run_until_parked();
    feed_session(cx, &view, id, &directory_report("/"));
    click(cx, "session.files");
    files.reply(1, "/", &[("etc", shellune_core::FileKind::Directory)]);
    pump_files(cx, &view);
    assert_eq!(remote_path(cx, &view, id).as_deref(), Some("/"));
    assert!(cx.update(|_window, app| view.read(app).files_follows(id)));
    let sent = files.requests().len();
    press_key(cx, "left");
    assert!(
        cx.update(|_window, app| view.read(app).files_follows(id)),
        "the step the column cannot take does not turn following off"
    );
    assert_eq!(
        files.requests().len(),
        sent,
        "nothing is asked for a directory that has no parent"
    );
    assert_eq!(remote_path(cx, &view, id).as_deref(), Some("/"));
}
#[gpui::test]
async fn following_opens_on_the_reported_directory_and_survives_the_background(
    cx: &mut TestAppContext,
) {
    // Three edges R15 has to hold: the report that arrived before the view opened is the
    // directory it opens on, a step up the column cannot take is not the user browsing,
    // and a report that arrives while another session is in front waits for its own.
    let (view, cx) = remote_view(cx);
    let id = live_remote(cx, &view);
    let files = FileAnswers::accepting();

    // 1. A report before the view exists is the directory the first listing asks for,
    //    and the note says so instead of "no directory reported yet".
    let channel = files.clone();
    cx.update(|_window, app| {
        view.update(app, |view, cx| {
            view.attach_files_for_test(id, "web", "deploy@10.0.0.5:22", Box::new(channel), cx);
        });
    });
    cx.run_until_parked();
    feed_session(cx, &view, id, &directory_report("/var/log"));
    click(cx, "session.files");
    let first = files.requests().first().cloned();
    assert!(
        matches!(&first, Some(shellune_core::BrowseRequest::List { path, .. }) if path == "/var/log"),
        "the first listing is the reported directory, not the login one: {first:?}"
    );
    files.reply(1, "/var/log", &[("syslog", shellune_core::FileKind::File)]);
    pump_files(cx, &view);
    assert_eq!(
        cx.update(|_window, app| view.read(app).files_follow_note(id)),
        Some(crate::app::files::FollowNote::Following {
            path: "/var/log".to_owned()
        }),
        "the column says it follows the directory it was asked for"
    );

    // 2. A report that arrives while another session is in front moves nothing until
    //    this session is the one on screen again.
    let _second = live_remote_second(cx, &view, id);
    feed_session(cx, &view, id, &directory_report("/etc"));
    assert_eq!(
        remote_path(cx, &view, id).as_deref(),
        Some("/var/log"),
        "the listing of a background session is left where it is"
    );
    show_remote_terminal(cx, &view, id);
    pump_files(cx, &view);
    let request = match files.requests().last().cloned() {
        Some(shellune_core::BrowseRequest::List { path, request }) => {
            assert_eq!(
                path, "/etc",
                "the report is followed once this session is in front"
            );
            request
        }
        other => panic!("coming back asks for the reported directory, got {other:?}"),
    };
    files.reply(request, "/etc", &[("hosts", shellune_core::FileKind::File)]);
    pump_files(cx, &view);
    assert_eq!(remote_path(cx, &view, id).as_deref(), Some("/etc"));
}
#[gpui::test]
async fn browsing_by_hand_stops_the_following_and_the_switch_takes_it_back(
    cx: &mut TestAppContext,
) {
    let (view, cx) = remote_view(cx);
    let id = live_remote(cx, &view);
    let answers = FileAnswers::accepting();
    open_files_for(cx, &view, id, &answers);
    answers.reply(
        1,
        "/home/deploy",
        &[("docs", shellune_core::FileKind::Directory)],
    );
    pump_files(cx, &view);
    feed_session(cx, &view, id, &directory_report("/var/log"));
    let request = match answers.requests().last().cloned() {
        Some(shellune_core::BrowseRequest::List { request, .. }) => request,
        other => panic!("following asks for the reported directory, got {other:?}"),
    };
    answers.reply(
        request,
        "/var/log",
        &[("syslog", shellune_core::FileKind::File)],
    );
    pump_files(cx, &view);
    assert_eq!(remote_path(cx, &view, id).as_deref(), Some("/var/log"));

    // The user clicks an ancestor breadcrumb: that is browsing, not following.
    click(cx, "files.crumb.0");
    assert!(
        !cx.update(|_window, app| view.read(app).files_follows(id)),
        "browsing by hand turns following off"
    );
    assert_eq!(
        cx.update(|_window, app| view.read(app).files_follow_note(id)),
        Some(crate::app::files::FollowNote::Manual)
    );

    // A later cd must not take the path the user chose.
    let before = answers.requests().len();
    feed_session(cx, &view, id, &directory_report("/etc"));
    assert_eq!(
        answers.requests().len(),
        before,
        "a manual path is not replaced by the next directory the shell reports"
    );

    // The switch returns to where the shell is now.
    click(cx, "files.follow");
    match answers.requests().last().cloned() {
        Some(shellune_core::BrowseRequest::List { path, request }) => {
            assert_eq!(
                path, "/etc",
                "the switch goes to the last reported directory"
            );
            answers.reply(request, "/etc", &[("hosts", shellune_core::FileKind::File)]);
        }
        other => panic!("following asks for the reported directory, got {other:?}"),
    }
    pump_files(cx, &view);
    assert_eq!(remote_path(cx, &view, id).as_deref(), Some("/etc"));
    assert!(cx.update(|_window, app| view.read(app).files_follows(id)));
}

#[gpui::test]
async fn a_directory_that_cannot_be_read_keeps_the_last_readable_one_and_says_why(
    cx: &mut TestAppContext,
) {
    let (view, cx) = remote_view(cx);
    let id = live_remote(cx, &view);
    let answers = FileAnswers::accepting();
    open_files_for(cx, &view, id, &answers);
    answers.reply(
        1,
        "/home/deploy",
        &[("docs", shellune_core::FileKind::Directory)],
    );
    pump_files(cx, &view);

    feed_session(cx, &view, id, &directory_report("/root/private"));
    let refused = match answers.requests().last().cloned() {
        Some(shellune_core::BrowseRequest::List { path, request }) => {
            assert_eq!(path, "/root/private");
            request
        }
        other => panic!("the reported directory is asked for, got {other:?}"),
    };
    answers.fail(
        refused,
        shellune_core::BrowseFailure::PermissionDenied {
            path: "/root/private".to_owned(),
        },
    );
    pump_files(cx, &view);
    // The window returns to the directory the server really listed.
    let back = match answers.requests().last().cloned() {
        Some(shellune_core::BrowseRequest::List { path, request }) => {
            assert_eq!(path, "/home/deploy");
            request
        }
        other => panic!("the last readable directory is listed again, got {other:?}"),
    };
    answers.reply(
        back,
        "/home/deploy",
        &[("docs", shellune_core::FileKind::Directory)],
    );
    pump_files(cx, &view);

    assert_eq!(remote_path(cx, &view, id).as_deref(), Some("/home/deploy"));
    assert_eq!(
        cx.update(|_window, app| view.read(app).files_follow_note(id)),
        Some(crate::app::files::FollowNote::Unreadable {
            path: "/root/private".to_owned()
        }),
        "the refusal is stated together with the last readable path"
    );
    // R4: the reason is in the switch's tooltip, after its state, and not in a warning
    // line under the path.
    assert!(
        cx.debug_bounds("files.follow.note").is_none(),
        "the remote column draws no follow note under its path"
    );
    let tooltip = cx.update(|_window, app| view.read(app).files_follow_tooltip_for_test(id));
    let strings = crate::app::copy::Locale::English.strings();
    assert!(
        tooltip.starts_with(strings.files_follow_on)
            && tooltip.contains(strings.files_follow_unreadable)
            && tooltip.contains("/root/private"),
        "the tooltip states the switch and why the column is not where the shell is: {tooltip:?}"
    );
}

#[gpui::test]
async fn the_follow_switch_is_a_keyboard_stop_and_answers_enter(cx: &mut TestAppContext) {
    let (view, cx) = remote_view(cx);
    let id = live_remote(cx, &view);
    let answers = FileAnswers::accepting();
    open_files_for(cx, &view, id, &answers);
    answers.reply(
        1,
        "/home/deploy",
        &[("docs", shellune_core::FileKind::Directory)],
    );
    pump_files(cx, &view);

    // The keyboard lands in the server column, which is where a session's files are
    // browsed from.
    cx.update(|window, app| view.read(app).focus_remote_files_for_test(window));
    cx.run_until_parked();
    assert_eq!(
        files_stop(cx, &view),
        Some((FileSource::Remote, FilesStop::Body))
    );

    // Tab walks the file view's controls until the switch has the ring.
    let mut reached = false;
    for _ in 0..8 {
        press_key(cx, "tab");
        if files_stop(cx, &view) == Some((FileSource::Remote, FilesStop::Follow)) {
            reached = true;
            break;
        }
    }
    assert!(reached, "the follow switch is reachable with the keyboard");

    // Enter presses it, exactly as a click does.
    press_key(cx, "enter");
    assert!(
        !cx.update(|_window, app| view.read(app).files_follows(id)),
        "Enter turns following off"
    );
    assert_eq!(
        files_stop(cx, &view),
        Some((FileSource::Remote, FilesStop::Follow)),
        "the ring stays on the switch it just pressed"
    );
    press_key(cx, "enter");
    assert!(cx.update(|_window, app| view.read(app).files_follows(id)));
    // Space answers as Enter does.
    press_key(cx, "space");
    assert!(
        !cx.update(|_window, app| view.read(app).files_follows(id)),
        "Space turns following off"
    );
    press_key(cx, "space");
    assert!(cx.update(|_window, app| view.read(app).files_follows(id)));
}

/// The names one column shows, in the order it shows them (R14).
fn column_rows(
    cx: &mut VisualTestContext,
    view: &Entity<ShelluneView>,
    id: SessionId,
    source: FileSource,
) -> Vec<String> {
    cx.update(|_window, app| view.read(app).files_rows_for_test(id, source))
}

/// The entries one column has marked (R14).
fn column_marked(
    cx: &mut VisualTestContext,
    view: &Entity<ShelluneView>,
    id: SessionId,
    source: FileSource,
) -> Vec<String> {
    cx.update(|_window, app| view.read(app).files_marked_for_test(id, source))
}

/// Every deletion the scripted connection was asked for, in the order it was asked (R14).
fn deleted_paths(answers: &FileAnswers) -> Vec<String> {
    answers
        .requests()
        .into_iter()
        .filter_map(|request| match request {
            shellune_core::BrowseRequest::Delete { path, .. } => Some(path),
            _ => None,
        })
        .collect()
}

/// The names as the columns report them, which is what an assertion compares.
fn names(list: &[&str]) -> Vec<String> {
    list.iter().map(|name| (*name).to_owned()).collect()
}

#[gpui::test]
async fn each_column_sorts_and_filters_its_own_listing(cx: &mut TestAppContext) {
    // R14 wants sorting and filtering to belong to one column: narrowing the server's
    // side must leave this computer's side alone, and neither may reorder the other.
    let (view, cx) = remote_view(cx);
    let id = live_remote(cx, &view);
    let (remote, _local) = open_both_sources(
        cx,
        &view,
        id,
        "/C:/work",
        &[
            ("b.txt", shellune_core::FileKind::File),
            ("a.txt", shellune_core::FileKind::File),
            ("logs", shellune_core::FileKind::Directory),
        ],
    );
    assert_eq!(
        column_rows(cx, &view, id, FileSource::Local),
        names(&["logs", "a.txt", "b.txt"]),
        "a folder stays first and the names run A to Z"
    );
    // The same key pressed again reverses the order, and the folder still leads.
    click(cx, "files.local.sort.name");
    assert_eq!(
        column_rows(cx, &view, id, FileSource::Local),
        names(&["logs", "b.txt", "a.txt"])
    );
    assert_eq!(
        column_rows(cx, &view, id, FileSource::Remote),
        names(&["docs", "notes.txt"]),
        "the server's column keeps its own order"
    );

    // A filter is read from the column it was typed into, and costs no request.
    let sent = remote.requests().len();
    cx.update(|_window, app| {
        view.update(app, |view, cx| {
            view.files_filter_set_for_test(id, FileSource::Remote, "note", cx);
        });
    });
    cx.run_until_parked();
    assert_eq!(
        column_rows(cx, &view, id, FileSource::Remote),
        names(&["notes.txt"])
    );
    assert_eq!(
        cx.update(|_window, app| { view.read(app).files_counts_for_test(id, FileSource::Remote) }),
        Some((1, 2)),
        "the column says how many names the filter lets through"
    );
    assert_eq!(
        column_rows(cx, &view, id, FileSource::Local),
        names(&["logs", "b.txt", "a.txt"]),
        "the other column is not filtered"
    );
    assert_eq!(
        remote.requests().len(),
        sent,
        "filtering a listing asks the server for nothing"
    );
}

#[gpui::test]
async fn marking_rows_with_the_pointer_uploads_every_marked_file(cx: &mut TestAppContext) {
    // R14 asks for a batch to be reachable with the pointer as well as the keyboard, and
    // R16 for every file to become its own task: one transfer carries one path.
    let (view, cx) = remote_view(cx);
    let id = live_remote(cx, &view);
    let (remote, _local) = open_both_sources(
        cx,
        &view,
        id,
        "/C:/work",
        &[
            ("a.txt", shellune_core::FileKind::File),
            ("b.txt", shellune_core::FileKind::File),
        ],
    );
    let transfers = TransferAnswers::accepting();
    let channel = transfers.clone();
    cx.update(|_window, app| {
        view.update(app, |view, cx| {
            view.attach_transfers_for_test(id, Box::new(channel), cx);
        });
    });
    cx.run_until_parked();

    // The box on each row is a target of its own.
    click(cx, "files.local.mark.0");
    click(cx, "files.local.mark.1");
    assert_eq!(
        column_marked(cx, &view, id, FileSource::Local),
        names(&["a.txt", "b.txt"])
    );
    click(cx, "files.local.mark.upload");
    let starts = transfers.starts();
    assert_eq!(starts.len(), 2, "one task per marked file: {starts:?}");
    let expected_first = if cfg!(windows) {
        "C:\\work\\a.txt"
    } else {
        "/C:/work/a.txt"
    };
    assert_eq!(
        starts[0].source.as_str(),
        expected_first,
        "the first task is the first marked row"
    );
    assert_eq!(
        column_marked(cx, &view, id, FileSource::Local),
        Vec::<String>::new(),
        "the batch is done, so nothing is left marked"
    );
    let _ = remote;
}

#[gpui::test]
async fn the_keyboard_marks_rows_and_a_batch_delete_names_every_entry(cx: &mut TestAppContext) {
    // R14: a batch is built with the keyboard (Space marks the row under the cursor and
    // moves on, Ctrl+A marks the column) and the question names every entry it covers,
    // while the requests go out one at a time.
    let (view, cx) = remote_view(cx);
    let id = live_remote(cx, &view);
    let files = FileAnswers::accepting();
    open_files_for(cx, &view, id, &files);
    files.reply(
        1,
        "/home/deploy",
        &[
            ("docs", shellune_core::FileKind::Directory),
            ("notes.txt", shellune_core::FileKind::File),
        ],
    );
    pump_files(cx, &view);
    assert_eq!(
        files_stop(cx, &view),
        Some((FileSource::Remote, FilesStop::Body)),
        "the listing holds the keys"
    );
    press_key(cx, "down");
    press_key(cx, "space");
    press_key(cx, "space");
    assert_eq!(
        column_marked(cx, &view, id, FileSource::Remote),
        names(&["docs", "notes.txt"]),
        "Space marks the row it is on and moves to the next"
    );

    click(cx, "files.mark.delete");
    assert_eq!(
        cx.update(|_window, app| { view.read(app).files_delete_question_for_test() }),
        Some(names(&["docs", "notes.txt"])),
        "the question names every entry it would delete"
    );
    cx.update(|_window, app| {
        view.update(app, |view, cx| view.submit_files_change_for_test(cx));
    });
    cx.run_until_parked();
    assert_eq!(
        deleted_paths(&files),
        names(&["/home/deploy/docs"]),
        "only the first deletion has been asked for"
    );
    files.changed(
        2,
        shellune_core::MutationOutcome::new(
            shellune_core::MutationAction::Delete {
                path: "/home/deploy/docs".to_owned(),
                kind: shellune_core::FileKind::Directory,
            },
            vec![shellune_core::MutationStep::done(
                "/home/deploy/docs",
                Some(shellune_core::FileKind::Directory),
            )],
        ),
    );
    pump_files(cx, &view);
    files.reply(
        3,
        "/home/deploy",
        &[("notes.txt", shellune_core::FileKind::File)],
    );
    pump_files(cx, &view);
    assert_eq!(
        deleted_paths(&files),
        names(&["/home/deploy/docs", "/home/deploy/notes.txt"]),
        "the second deletion follows once the first answer and its listing arrived"
    );
}

#[gpui::test]
async fn a_wide_window_docks_the_files_beside_the_terminal_and_keeps_both(cx: &mut TestAppContext) {
    // R14 asks a wide window to show the terminal and the files at once, and asks a
    // layout switch to change neither the terminal nor either column's path.
    let (view, cx) = remote_view(cx);
    cx.simulate_resize(size(px(1680.0), px(940.0)));
    cx.run_until_parked();
    let id = live_remote(cx, &view);
    let files = FileAnswers::accepting();
    open_files_for(cx, &view, id, &files);
    files.reply(
        1,
        "/home/deploy",
        &[
            ("docs", shellune_core::FileKind::Directory),
            ("notes.txt", shellune_core::FileKind::File),
        ],
    );
    pump_files(cx, &view);
    assert!(
        cx.update(|_window, app| view.read(app).files_docked_for_test()),
        "a window this wide docks the files beside the terminal"
    );
    let split = bounds_of(cx, "files.split");
    assert!(
        split.size.height > px(0.0),
        "the two share one row: {split:?}"
    );
    let screen = cx.update(|_window, app| {
        view.read(app)
            .pane_of(id)
            .map(|pane| pane.read(app).visible_text().join("\n"))
            .unwrap_or_default()
    });
    assert!(
        screen.contains("remote ready"),
        "the terminal is still drawn beside the files: {screen:?}"
    );

    // The focus switch gives the files the whole width; the terminal and the paths stay.
    let docked_width = bounds_of(cx, "files.panel").size.width;
    click(cx, "files.mode.focus");
    assert!(!cx.update(|_window, app| view.read(app).files_docked_for_test()));
    // Focused, the file view has the whole client area rather than half of it. The
    // selector of the docked row is not asked about here: a removed selector keeps the
    // bounds of the frame that drew it.
    let focused_width = bounds_of(cx, "files.panel").size.width;
    assert!(
        focused_width > docked_width,
        "the files take the terminal's width too: {focused_width:?} against {docked_width:?}"
    );
    assert_eq!(
        remote_path(cx, &view, id).as_deref(),
        Some("/home/deploy"),
        "the path survives the layout switch"
    );
    click(cx, "files.mode.dock");
    assert!(cx.update(|_window, app| view.read(app).files_docked_for_test()));
    assert!(cx.debug_bounds("files.split").is_some());
    let docked_again = bounds_of(cx, "files.panel").size.width;
    assert!(
        docked_again < focused_width,
        "the terminal has its half back: {docked_again:?}"
    );
    assert_eq!(remote_path(cx, &view, id).as_deref(), Some("/home/deploy"));
    assert_eq!(
        cx.update(|_window, app| view.read(app).active_session()),
        Some(id),
        "the terminal is the same session in every arrangement"
    );
}
#[gpui::test]
async fn the_focus_switch_is_only_offered_where_the_window_can_dock(cx: &mut TestAppContext) {
    // R14 asks for a switch between the docked and the focused layout. A window narrower
    // than DOCK_MIN_WIDTH has no docked layout to leave, so the switch used to be drawn
    // anyway and did nothing but relabel itself: the files already had the terminal's
    // place. It is offered only where the press changes the arrangement.
    let (view, cx) = remote_view(cx);
    let id = live_remote(cx, &view);
    let files = FileAnswers::accepting();
    open_files_for(cx, &view, id, &files);
    files.reply(
        1,
        "/home/deploy",
        &[
            ("docs", shellune_core::FileKind::Directory),
            ("notes.txt", shellune_core::FileKind::File),
        ],
    );
    pump_files(cx, &view);

    // The default 1120-pixel window: the files take the terminal's place, and the bar
    // does not offer a second arrangement that would render identically.
    assert!(
        !cx.update(|_window, app| view.read(app).files_docked_for_test()),
        "a window this narrow does not dock the files"
    );
    assert!(
        cx.debug_bounds("files.layout.dual").is_some(),
        "the two columns share the whole width instead"
    );
    assert!(
        cx.debug_bounds("files.mode.focus").is_none(),
        "no layout switch is drawn where both modes render the same"
    );
    assert!(
        cx.debug_bounds("files.mode.dock").is_none(),
        "and the other label of that switch is not drawn either"
    );

    // A window that really can dock gets the switch, and the press changes the layout.
    cx.simulate_resize(size(px(1680.0), px(940.0)));
    cx.run_until_parked();
    let switch = bounds_of(cx, "files.mode.focus");
    assert!(
        switch.size.width > px(0.0),
        "a dockable window offers the focus switch: {switch:?}"
    );
    let docked_width = bounds_of(cx, "files.panel").size.width;
    click(cx, "files.mode.focus");
    assert!(!cx.update(|_window, app| view.read(app).files_docked_for_test()));
    let focused_width = bounds_of(cx, "files.panel").size.width;
    assert!(
        focused_width > docked_width,
        "the focused mode gives the files the terminal's half: {focused_width:?} against {docked_width:?}"
    );
    click(cx, "files.mode.dock");
    assert!(cx.update(|_window, app| view.read(app).files_docked_for_test()));
    assert!(
        bounds_of(cx, "files.panel").size.width < focused_width,
        "the terminal comes back on the same press"
    );
}

#[gpui::test]
async fn the_delete_key_covers_the_batch_the_menu_deletes(cx: &mut TestAppContext) {
    // R14: one marked state has one answer. The menu on a marked row says "Delete the
    // selection" and deletes the marks; the Delete key used to delete only the row under
    // the cursor, so the two entry points disagreed about the same selection.
    let (view, cx) = remote_view(cx);
    let id = live_remote(cx, &view);
    let files = FileAnswers::accepting();
    open_files_for(cx, &view, id, &files);
    files.reply(
        1,
        "/home/deploy",
        &[
            ("docs", shellune_core::FileKind::Directory),
            ("notes.txt", shellune_core::FileKind::File),
        ],
    );
    pump_files(cx, &view);
    assert_eq!(
        files_stop(cx, &view),
        Some((FileSource::Remote, FilesStop::Body)),
        "the listing holds the keys"
    );
    press_key(cx, "down");
    press_key(cx, "space");
    press_key(cx, "space");
    assert_eq!(
        column_marked(cx, &view, id, FileSource::Remote),
        names(&["docs", "notes.txt"]),
        "two rows are marked"
    );

    let handled = cx.update(|window, app| {
        view.update(app, |view, cx| {
            view.files_key_for_test(id, FileSource::Remote, "delete", false, window, cx)
        })
    });
    assert!(handled, "Delete belongs to the column");
    let by_key = cx.update(|_window, app| view.read(app).files_delete_question_for_test());
    assert_eq!(
        by_key,
        Some(names(&["docs", "notes.txt"])),
        "the key asks about every marked entry, not only the row it sits on"
    );
    press_key(cx, "escape");
    assert!(
        !cx.update(|_window, app| view.read(app).files_question_open()),
        "the question closes again"
    );

    // The menu on one of those marked rows covers exactly the same entries.
    right_click(cx, "files.entry.1");
    click(cx, "files.menu.delete");
    let by_menu = cx.update(|_window, app| view.read(app).files_delete_question_for_test());
    assert_eq!(
        by_menu, by_key,
        "the menu and the key delete the same entries for one selection"
    );
}

#[gpui::test]
async fn a_batch_counts_the_tasks_it_started_and_says_what_it_left_out(cx: &mut TestAppContext) {
    // R14: a batch reports what really happened. A folder among the marks is not a task -
    // a batch copies one path per task and never expands a folder into a tree behind the
    // user's back - so the count leaves it out and the strip says how many were skipped,
    // instead of announcing an upload that never started.
    let (view, cx) = remote_view(cx);
    let id = live_remote(cx, &view);
    let (remote, local) = open_both_sources(
        cx,
        &view,
        id,
        "/C:/work",
        &[
            ("logs", shellune_core::FileKind::Directory),
            ("a.txt", shellune_core::FileKind::File),
            ("b.txt", shellune_core::FileKind::File),
        ],
    );
    let transfers = TransferAnswers::accepting();
    let channel = transfers.clone();
    cx.update(|_window, app| {
        view.update(app, |view, cx| {
            view.attach_transfers_for_test(id, Box::new(channel), cx);
        });
    });
    cx.run_until_parked();
    let _ = local;

    // The whole local listing is marked: one folder and two files.
    click(cx, "files.local.mark.0");
    click(cx, "files.local.mark.1");
    click(cx, "files.local.mark.2");
    assert_eq!(
        column_marked(cx, &view, id, FileSource::Local).len(),
        3,
        "three entries are marked"
    );
    click(cx, "files.local.mark.upload");
    let starts = transfers.starts();
    assert_eq!(
        starts.len(),
        2,
        "one task per marked file and none for the folder: {starts:?}"
    );
    let strings = Locale::default().strings();
    assert_eq!(
        cx.update(|_window, app| view.read(app).toast_titles()),
        vec![copy::fill(
            strings.files_uploaded_selected,
            &[("count", "2")]
        )],
        "the toast counts the tasks that exist, not the marks that were made"
    );
    assert_eq!(
        cx.update(|_window, app| view.read(app).transfer_skipped_folders_for_test(id)),
        Some(copy::fill(
            strings.files_batch_folders_skipped,
            &[("count", "1")]
        )),
        "the folder that was left out is stated once, with its own reason"
    );
    assert!(
        cx.debug_bounds("transfers.skipped").is_some(),
        "the line is on screen beside the transfer list"
    );
    let _ = (remote, local);
}

#[gpui::test]
