#[gpui::test]
async fn with_automatic_sync_off_a_change_stays_local_until_upload_now(cx: &mut TestAppContext) {
    let server = shellune_sync::testing::WebDavServer::start(SYNC_USER, SYNC_PASSWORD);
    let dir = TempDir::new("sync-manual");
    seed(
        &dir.store(),
        vec![stored_host("alpha", "10.0.0.1", 22, "root", None)],
    );
    let secrets = Arc::new(shellune_storage::MemorySecrets::new());
    configure_sync(&dir, &secrets, &server, false);
    let (view, cx) = sync_window(cx, &dir, &secrets, Destination::Settings);
    assert_eq!(
        sync_progress(&view, cx).0,
        0,
        "no pull at start while it is off"
    );
    assert!(server.requests().is_empty());

    let alpha = first_host_id(&view, cx);
    toggle_favorite(&view, cx, alpha);
    after_debounce(cx);
    after_poll(cx);
    assert!(
        server.requests().is_empty(),
        "a change is not uploaded while automatic sync is off"
    );
    assert!(server.file(&cloud_path()).is_none());

    click(cx, "settings.category.sync");
    click(cx, "settings.sync.upload");
    assert_eq!(
        cloud_host_names(&server),
        vec!["alpha"],
        "upload now writes the cloud"
    );
    assert!(cloud_document(&server).shared().hosts().is_favorite(alpha));
    assert_eq!(sync_progress(&view, cx).2, None);
}

#[gpui::test]
async fn a_saved_change_is_uploaded_after_the_debounce(cx: &mut TestAppContext) {
    let server = shellune_sync::testing::WebDavServer::start(SYNC_USER, SYNC_PASSWORD);
    let dir = TempDir::new("sync-auto-upload");
    seed(
        &dir.store(),
        vec![stored_host("alpha", "10.0.0.1", 22, "root", None)],
    );
    let secrets = Arc::new(shellune_storage::MemorySecrets::new());
    configure_sync(&dir, &secrets, &server, true);
    let (view, cx) = sync_window(cx, &dir, &secrets, Destination::Hosts);
    // The first sync at start found an empty cloud and uploaded.
    assert_eq!(cloud_host_names(&server), vec!["alpha"]);

    let alpha = first_host_id(&view, cx);
    toggle_favorite(&view, cx, alpha);
    assert!(
        !cloud_document(&server).shared().hosts().is_favorite(alpha),
        "nothing is sent before the debounce runs out"
    );
    after_debounce(cx);
    assert!(
        cloud_document(&server).shared().hosts().is_favorite(alpha),
        "the change reached the cloud"
    );
    assert_eq!(sync_marker(&view, cx), None);
}

#[gpui::test]
async fn another_machine_s_host_arrives_at_start_and_on_the_next_check(cx: &mut TestAppContext) {
    let server = shellune_sync::testing::WebDavServer::start(SYNC_USER, SYNC_PASSWORD);
    let machine_a = TempDir::new("sync-a");
    seed(
        &machine_a.store(),
        vec![stored_host("alpha", "10.0.0.1", 22, "root", None)],
    );
    let a = other_machine(&machine_a, &server);
    assert!(matches!(
        a.sync().expect("A uploads"),
        shellune_sync::SyncOutcome::Uploaded(_)
    ));

    // B starts with nothing and pulls what A wrote.
    let machine_b = TempDir::new("sync-b");
    let secrets = Arc::new(shellune_storage::MemorySecrets::new());
    configure_sync(&machine_b, &secrets, &server, true);
    let (view, cx) = sync_window(cx, &machine_b, &secrets, Destination::Hosts);
    assert_eq!(host_names(&view, cx), vec!["alpha"], "pulled at start");

    // A adds a host; B's next check brings it in without a restart.
    seed(
        &machine_a.store(),
        vec![
            stored_host("alpha", "10.0.0.1", 22, "root", None),
            stored_host("beta", "10.0.0.2", 22, "root", None),
        ],
    );
    let _ = a.sync().expect("A uploads again");
    after_poll(cx);
    assert_eq!(host_names(&view, cx), vec!["alpha", "beta"]);
    assert_eq!(
        machine_b.store().load().expect("reads").hosts().len(),
        2,
        "and it is saved on B"
    );
    // Applying the pull did not send it back.
    let puts = put_count(&server);
    after_debounce(cx);
    assert_eq!(put_count(&server), puts, "a pull is not uploaded again");
}

/// Sets up a conflict: A and B synced once, then both changed, and A uploaded first.
fn conflicting_machines<'a>(
    cx: &'a mut TestAppContext,
    server: &shellune_sync::testing::WebDavServer,
    machine_a: &TempDir,
    machine_b: &TempDir,
) -> (
    Entity<ShelluneView>,
    &'a mut VisualTestContext,
    shellune_sync::SyncService,
) {
    seed(
        &machine_a.store(),
        vec![stored_host("alpha", "10.0.0.1", 22, "root", None)],
    );
    let a = other_machine(machine_a, server);
    let _ = a.sync().expect("A uploads");
    let secrets = Arc::new(shellune_storage::MemorySecrets::new());
    configure_sync(machine_b, &secrets, server, true);
    let (view, cx) = sync_window(cx, machine_b, &secrets, Destination::Settings);
    assert_eq!(host_names(&view, cx), vec!["alpha"]);

    seed(
        &machine_a.store(),
        vec![
            stored_host("alpha", "10.0.0.1", 22, "root", None),
            stored_host("from-a", "10.0.0.7", 22, "root", None),
        ],
    );
    let _ = a.sync().expect("A uploads its change");
    let alpha = first_host_id(&view, cx);
    toggle_favorite(&view, cx, alpha);
    after_debounce(cx);
    (view, cx, a)
}

#[gpui::test]
async fn a_conflict_asks_and_cancel_keeps_both_sides(cx: &mut TestAppContext) {
    let server = shellune_sync::testing::WebDavServer::start(SYNC_USER, SYNC_PASSWORD);
    let (machine_a, machine_b) = (TempDir::new("conflict-a"), TempDir::new("conflict-b"));
    let (view, cx, _a) = conflicting_machines(cx, &server, &machine_a, &machine_b);
    assert!(
        sync_conflict_open(&view, cx),
        "both sides changed, so the window asks"
    );
    assert!(cx.debug_bounds("sync.conflict.dialog").is_some());
    assert_eq!(cloud_host_names(&server), vec!["alpha", "from-a"]);

    click(cx, "sync.conflict.cancel");
    assert!(!sync_conflict_open(&view, cx));
    assert_eq!(
        host_names(&view, cx),
        vec!["alpha"],
        "nothing local was replaced"
    );
    assert_eq!(
        cloud_host_names(&server),
        vec!["alpha", "from-a"],
        "nothing in the cloud was replaced"
    );
    assert_eq!(sync_marker(&view, cx), Some("conflict"));
    assert!(cx.debug_bounds("topbar.sync").is_some());

    // An automatic check does not ask again while the conflict is put away...
    after_poll(cx);
    assert!(!sync_conflict_open(&view, cx));
    // ...and the settings page asks again on request.
    click(cx, "settings.category.sync");
    click(cx, "settings.sync.conflict");
    assert!(sync_conflict_open(&view, cx));
    // Escape is the same as cancel.
    cx.simulate_keystrokes("escape");
    cx.run_until_parked();
    assert!(!sync_conflict_open(&view, cx));
    assert_eq!(host_names(&view, cx), vec!["alpha"]);
    assert_eq!(cloud_host_names(&server), vec!["alpha", "from-a"]);
}

#[gpui::test]
async fn only_connecting_here_merges_with_the_cloud_without_asking(cx: &mut TestAppContext) {
    let server = shellune_sync::testing::WebDavServer::start(SYNC_USER, SYNC_PASSWORD);
    let (machine_a, machine_b) = (TempDir::new("merge-a"), TempDir::new("merge-b"));
    seed(
        &machine_a.store(),
        vec![
            stored_host("alpha", "10.0.0.1", 22, "root", None),
            stored_host("beta", "10.0.0.2", 22, "root", None),
        ],
    );
    let a = other_machine(&machine_a, &server);
    let _ = a.sync().expect("A uploads");
    let secrets = Arc::new(shellune_storage::MemorySecrets::new());
    configure_sync(&machine_b, &secrets, &server, true);
    let (view, cx) = sync_window(cx, &machine_b, &secrets, Destination::Hosts);
    assert_eq!(host_names(&view, cx), vec!["alpha", "beta"]);

    // A adds a host and uploads; B meanwhile only connects to alpha.
    let store_a = machine_a.store();
    let mut book_a = store_a.load().expect("A's hosts read");
    book_a
        .insert(stored_host("from-a", "10.0.0.7", 22, "root", None))
        .expect("inserted");
    store_a.save(&book_a).expect("saved");
    let _ = a.sync().expect("A uploads its change");
    let alpha = first_host_id(&view, cx);
    cx.update(|_window, app| {
        view.update(app, |view, cx| {
            assert!(view.record_host_connection(alpha, 1_800_000_000, cx));
        });
    });
    cx.run_until_parked();
    after_debounce(cx);

    assert!(
        !sync_conflict_open(&view, cx),
        "only connecting here is no conflict"
    );
    assert_eq!(sync_marker(&view, cx), None);
    assert_eq!(
        host_names(&view, cx),
        vec!["alpha", "beta", "from-a"],
        "A's host is listed without a restart"
    );
    let recent = |book: &HostBook| {
        book.recent_of(alpha)
            .map(shellune_storage::RecentConnection::last_connected_unix)
    };
    assert_eq!(
        cx.update(|_window, app| recent(view.read(app).book())),
        Some(1_800_000_000),
        "B's connection is still listed"
    );
    assert_eq!(
        recent(&machine_b.store().load().expect("B's hosts read")),
        Some(1_800_000_000)
    );
    assert_eq!(
        recent(cloud_document(&server).shared().hosts()),
        Some(1_800_000_000),
        "and it reached the cloud"
    );
    assert!(
        shellune_storage::SnapshotStore::at(machine_b.path())
            .list()
            .iter()
            .any(|snapshot| snapshot.reason().starts_with("sync-merge")),
        "the data replaced here was copied aside first"
    );
    // A takes B's connection on its next sync, and nothing is sent back again.
    assert!(matches!(
        a.sync().expect("A syncs"),
        shellune_sync::SyncOutcome::Pulled(_)
    ));
    assert_eq!(
        recent(&machine_a.store().load().expect("A's hosts read")),
        Some(1_800_000_000)
    );
    let puts = put_count(&server);
    after_poll(cx);
    assert_eq!(put_count(&server), puts);
    assert_eq!(sync_progress(&view, cx).2, None);
}

#[gpui::test]
async fn use_cloud_data_replaces_this_computer_and_keeps_a_snapshot(cx: &mut TestAppContext) {
    let server = shellune_sync::testing::WebDavServer::start(SYNC_USER, SYNC_PASSWORD);
    let (machine_a, machine_b) = (TempDir::new("remote-a"), TempDir::new("remote-b"));
    let (view, cx, _a) = conflicting_machines(cx, &server, &machine_a, &machine_b);
    assert!(sync_conflict_open(&view, cx));
    click(cx, "sync.conflict.remote");
    assert_eq!(host_names(&view, cx), vec!["alpha", "from-a"]);
    assert_eq!(sync_marker(&view, cx), None);
    let snapshots = shellune_storage::SnapshotStore::at(machine_b.path()).list();
    let kept = snapshots
        .iter()
        .find(|snapshot| snapshot.reason().starts_with("sync-use-remote"))
        .expect("the data replaced here was copied aside first");
    let before = HostStore::at(kept.path()).load().expect("the copy reads");
    assert_eq!(before.hosts().len(), 1);
    assert!(
        before.is_favorite(before.hosts()[0].id()),
        "the copy is this computer's data before the choice"
    );
}

#[gpui::test]
async fn use_this_computer_replaces_the_cloud_and_keeps_its_file(cx: &mut TestAppContext) {
    let server = shellune_sync::testing::WebDavServer::start(SYNC_USER, SYNC_PASSWORD);
    let (machine_a, machine_b) = (TempDir::new("local-a"), TempDir::new("local-b"));
    let (view, cx, a) = conflicting_machines(cx, &server, &machine_a, &machine_b);
    assert!(sync_conflict_open(&view, cx));
    click(cx, "sync.conflict.local");
    assert_eq!(host_names(&view, cx), vec!["alpha"]);
    assert_eq!(
        cloud_host_names(&server),
        vec!["alpha"],
        "the cloud took this computer's data"
    );
    let alpha = first_host_id(&view, cx);
    assert!(cloud_document(&server).shared().hosts().is_favorite(alpha));
    let snapshots = shellune_storage::SnapshotStore::at(machine_b.path()).list();
    let kept = snapshots
        .iter()
        .find(|snapshot| snapshot.reason().starts_with("sync-use-local"))
        .expect("the cloud file replaced was copied aside first");
    let file = std::fs::read(kept.path().join(shellune_sync::REMOTE_FILE_NAME))
        .expect("the cloud file is in the snapshot");
    assert!(String::from_utf8_lossy(&file).contains("from-a"));
    assert_eq!(sync_marker(&view, cx), None);
    // A had nothing unsynced, so its next sync takes the choice made here.
    assert!(matches!(
        a.sync().expect("A checks"),
        shellune_sync::SyncOutcome::Pulled(_)
    ));
    assert_eq!(
        machine_a.store().load().expect("reads").hosts().len(),
        1,
        "the other machine follows the data that was kept"
    );
}

#[gpui::test]
async fn a_failed_sync_keeps_the_change_shows_a_marker_and_is_retried(cx: &mut TestAppContext) {
    let server = shellune_sync::testing::WebDavServer::start(SYNC_USER, SYNC_PASSWORD);
    let dir = TempDir::new("sync-offline");
    seed(
        &dir.store(),
        vec![stored_host("alpha", "10.0.0.1", 22, "root", None)],
    );
    let secrets = Arc::new(shellune_storage::MemorySecrets::new());
    configure_sync(&dir, &secrets, &server, true);
    let (view, cx) = sync_window(cx, &dir, &secrets, Destination::Hosts);
    assert_eq!(cloud_host_names(&server), vec!["alpha"]);

    server.set_offline(true);
    let alpha = first_host_id(&view, cx);
    toggle_favorite(&view, cx, alpha);
    after_debounce(cx);
    let (_, busy, failure) = sync_progress(&view, cx);
    assert!(!busy);
    let failure = failure.expect("the failure is kept");
    assert!(
        failure.starts_with(copy::ENGLISH_SYNC.error_unreachable),
        "{failure}"
    );
    assert!(
        dir.store().load().expect("reads").is_favorite(alpha),
        "the change is saved on this computer"
    );
    assert_eq!(sync_marker(&view, cx), Some("failed"));
    assert!(cx.debug_bounds("topbar.sync").is_some());
    let status = cx.update(|_window, app| view.read(app).sync_status_for_test().0);
    assert!(status.contains("Failed"), "{status}");

    // The network is back: the next check sends the change.
    server.set_offline(false);
    after_poll(cx);
    assert_eq!(sync_progress(&view, cx).2, None);
    assert_eq!(sync_marker(&view, cx), None);
    assert!(cloud_document(&server).shared().hosts().is_favorite(alpha));

    // The marker leads to the sync settings.
    server.set_offline(true);
    toggle_favorite(&view, cx, alpha);
    after_debounce(cx);
    assert_eq!(sync_marker(&view, cx), Some("failed"));
    click(cx, "topbar.sync");
    assert_eq!(destination_of(&view, cx), Destination::Settings);
    assert_eq!(
        cx.update(|_window, app| view.read(app).settings_page_id().0),
        "sync"
    );
}

/// The host names saved in a data directory, sorted.
fn names_on_disk(dir: &TempDir) -> Vec<String> {
    let mut names: Vec<String> = dir
        .store()
        .load()
        .expect("the host file reads")
        .hosts()
        .iter()
        .map(|host| host.name().to_owned())
        .collect();
    names.sort();
    names
}

fn hold_sync_finish(view: &Entity<ShelluneView>, cx: &mut VisualTestContext) {
    cx.update(|_window, app| view.update(app, |view, _cx| view.hold_sync_finish_for_test()));
}

fn sync_finish_held(view: &Entity<ShelluneView>, cx: &mut VisualTestContext) -> bool {
    cx.update(|_window, app| view.read(app).sync_finish_held_for_test())
}

fn release_sync_finish(view: &Entity<ShelluneView>, cx: &mut VisualTestContext) {
    cx.update(|_window, app| {
        view.update(app, |view, cx| view.release_sync_finish_for_test(cx));
    });
    cx.run_until_parked();
}

fn data_writes_held(view: &Entity<ShelluneView>, cx: &mut VisualTestContext) -> bool {
    cx.update(|_window, app| view.read(app).data_writes_held_for_test())
}

/// The race the window must not lose (R8, R10): a pull has written another machine's
/// records to disk, and before the window reads them back it saves an edit of its own.
/// The save must not write the window's stale copy over the records that arrived, and
/// the edit must not be lost either: both end up on disk, in the window and - without
/// a conflict question - in the cloud.
#[gpui::test]
async fn an_edit_saved_between_a_pull_and_its_adoption_keeps_what_arrived(cx: &mut TestAppContext) {
    let server = shellune_sync::testing::WebDavServer::start(SYNC_USER, SYNC_PASSWORD);
    let machine_a = TempDir::new("race-a");
    seed(
        &machine_a.store(),
        vec![stored_host("alpha", "10.0.0.1", 22, "root", None)],
    );
    let a = other_machine(&machine_a, &server);
    let _ = a.sync().expect("A uploads");

    let machine_b = TempDir::new("race-b");
    let secrets = Arc::new(shellune_storage::MemorySecrets::new());
    configure_sync(&machine_b, &secrets, &server, true);
    let (view, cx) = sync_window(cx, &machine_b, &secrets, Destination::Hosts);
    assert_eq!(host_names(&view, cx), vec!["alpha"], "pulled at start");
    let alpha = first_host_id(&view, cx);

    // A adds a host, keeping alpha as it is, and uploads it.
    let mut book = machine_a.store().load().expect("A reads");
    book.insert(stored_host("beta", "10.0.0.2", 22, "root", None))
        .expect("beta is added");
    machine_a.store().save(&book).expect("A saves");
    let _ = a.sync().expect("A uploads again");

    // B's next check writes what A sent; the window has not read it back yet.
    hold_sync_finish(&view, cx);
    after_poll(cx);
    assert!(
        sync_finish_held(&view, cx),
        "the job is done, its adoption is not"
    );
    assert_eq!(names_on_disk(&machine_b), vec!["alpha", "beta"]);
    assert_eq!(
        host_names(&view, cx),
        vec!["alpha"],
        "the window still shows the old book"
    );
    assert!(data_writes_held(&view, cx));

    // In that gap the window saves: a favourite, and a connection that just came up.
    toggle_favorite(&view, cx, alpha);
    cx.update(|_window, app| {
        view.update(app, |view, cx| {
            assert!(view.record_host_connection(alpha, 1_800_000_000, cx));
        });
    });
    cx.run_until_parked();
    assert_eq!(
        names_on_disk(&machine_b),
        vec!["alpha", "beta"],
        "the saves did not write the stale book over the records that arrived"
    );
    assert!(
        cx.update(|_window, app| view.read(app).book().is_favorite(alpha)),
        "the edit shows at once"
    );

    // The window takes the job in: the held edits are merged onto what arrived.
    release_sync_finish(&view, cx);
    assert!(!data_writes_held(&view, cx));
    assert_eq!(host_names(&view, cx), vec!["alpha", "beta"]);
    let on_disk = machine_b.store().load().expect("B reads");
    assert_eq!(names_on_disk(&machine_b), vec!["alpha", "beta"]);
    assert!(on_disk.is_favorite(alpha), "the favourite was kept");
    assert_eq!(
        on_disk
            .recent_of(alpha)
            .map(|recent| recent.last_connected_unix()),
        Some(1_800_000_000),
        "and so was the recorded connection"
    );

    // The merged data goes up as an ordinary change: no conflict, nothing lost.
    after_debounce(cx);
    assert!(!sync_conflict_open(&view, cx));
    assert_eq!(sync_marker(&view, cx), None);
    assert_eq!(cloud_host_names(&server), vec!["alpha", "beta"]);
    assert!(cloud_document(&server).shared().hosts().is_favorite(alpha));

    // A keeps its own host and receives B's favourite.
    assert!(matches!(
        a.sync().expect("A checks"),
        shellune_sync::SyncOutcome::Pulled(_)
    ));
    assert_eq!(names_on_disk(&machine_a), vec!["alpha", "beta"]);
    assert!(
        machine_a
            .store()
            .load()
            .expect("A reads")
            .is_favorite(alpha)
    );
}

fn exit_waiting(view: &Entity<ShelluneView>, cx: &mut VisualTestContext) -> bool {
    cx.update(|_window, app| view.read(app).exit_waiting_for_test())
}

/// Closing the window while a sync holds the window's saves back (R8): a save the
/// window already showed must reach the disk before the window goes. The close waits
/// for the job, the held edits - a new host with a remembered password among them -
/// are written when it ends, and only then is the window removed, so the password in
/// the credential store belongs to a host that is saved.
#[gpui::test]
async fn closing_while_saves_are_held_writes_them_before_the_window_goes(cx: &mut TestAppContext) {
    let server = shellune_sync::testing::WebDavServer::start(SYNC_USER, SYNC_PASSWORD);
    let dir = TempDir::new("close-held");
    seed(
        &dir.store(),
        vec![stored_host("alpha", "10.0.0.1", 22, "root", None)],
    );
    let secrets = Arc::new(shellune_storage::MemorySecrets::new());
    configure_sync(&dir, &secrets, &server, true);
    let (view, cx) = sync_window(cx, &dir, &secrets, Destination::Hosts);
    assert_eq!(cloud_host_names(&server), vec!["alpha"]);
    let alpha = first_host_id(&view, cx);

    // A check runs; its end is held, so the window's saves are held back.
    hold_sync_finish(&view, cx);
    after_poll(cx);
    assert!(sync_finish_held(&view, cx));
    assert!(data_writes_held(&view, cx));
    assert!(
        request_real_close(cx, &view),
        "with nothing held back a close does not wait"
    );
    assert!(!exit_waiting(&view, cx));

    // The window saves a favourite and a new host with a password meanwhile.
    toggle_favorite(&view, cx, alpha);
    fill_new_host(cx);
    click(cx, "hosts.auth.remote.method.password");
    type_into(cx, "hosts.field.secret", "s3cret-pass");
    click(cx, "hosts.save");
    let added = cx
        .update(|_window, app| {
            view.read(app)
                .book()
                .hosts()
                .iter()
                .find(|host| host.name() == "box")
                .map(shellune_core::HostConfig::id)
        })
        .expect("the host shows as saved");
    assert_eq!(
        names_on_disk(&dir),
        vec!["alpha"],
        "the saves are held back"
    );
    assert!(
        shellune_storage::SecretStore::load(&*secrets, added)
            .expect("reads")
            .is_some(),
        "the password is in the credential store already"
    );

    // The close waits for the sync instead of dropping what is held.
    assert!(!request_real_close(cx, &view), "the close waits");
    assert!(exit_waiting(&view, cx));
    assert!(
        cx.update(|_window, app| view.read(app).toast_titles())
            .iter()
            .any(|title| title == copy::ENGLISH_SYNC.exit_waits),
        "the wait is explained"
    );
    assert!(!request_real_close(cx, &view), "asking again still waits");
    assert_eq!(names_on_disk(&dir), vec!["alpha"]);
    assert_eq!(cx.windows().len(), 1);

    // The job ends: the held edits are written, then the window goes.
    release_sync_finish(&view, cx);
    cx.run_until_parked();
    assert_eq!(names_on_disk(&dir), vec!["alpha", "box"]);
    let on_disk = dir.store().load().expect("reads");
    assert!(on_disk.is_favorite(alpha), "the favourite reached the disk");
    assert!(
        on_disk.hosts().iter().any(|host| host.id() == added),
        "the password belongs to a saved host"
    );
    assert!(
        cx.windows().is_empty(),
        "the window closed once they were written"
    );
}

/// When the files cannot be read after the writer, the held edits are not written
/// whole over them (that could drop what the writer put there): the files stay as
/// they are, the user is told which changes to make again, and a close that waited
/// for those saves is called off so the notice can be read.
#[gpui::test]
async fn held_saves_are_not_written_over_files_that_cannot_be_read(cx: &mut TestAppContext) {
    let server = shellune_sync::testing::WebDavServer::start(SYNC_USER, SYNC_PASSWORD);
    let dir = TempDir::new("held-unreadable");
    seed(
        &dir.store(),
        vec![stored_host("alpha", "10.0.0.1", 22, "root", None)],
    );
    let secrets = Arc::new(shellune_storage::MemorySecrets::new());
    configure_sync(&dir, &secrets, &server, true);
    let (view, cx) = sync_window(cx, &dir, &secrets, Destination::Hosts);
    let alpha = first_host_id(&view, cx);

    hold_sync_finish(&view, cx);
    after_poll(cx);
    assert!(sync_finish_held(&view, cx));
    toggle_favorite(&view, cx, alpha);
    assert!(!request_real_close(cx, &view), "the close waits");

    // Something leaves the host file unreadable before the window takes the job in.
    let path = dir.path().join(shellune_storage::FILE_NAME);
    std::fs::write(&path, "{ not json").expect("written");
    release_sync_finish(&view, cx);

    assert_eq!(
        std::fs::read_to_string(&path).expect("reads"),
        "{ not json",
        "the window's copy was not written over the file"
    );
    assert!(!data_writes_held(&view, cx));
    assert!(!exit_waiting(&view, cx), "the close was called off");
    assert_eq!(cx.windows().len(), 1, "the window stays");
    let titles = cx.update(|_window, app| view.read(app).toast_titles());
    for expected in [
        copy::ENGLISH_SYNC.held_dropped,
        copy::ENGLISH_SYNC.held_failed,
        copy::ENGLISH_SYNC.exit_stopped,
    ] {
        assert!(
            titles.iter().any(|title| title == expected),
            "{expected:?} in {titles:?}"
        );
    }
    assert!(
        !cx.update(|_window, app| view.read(app).book().is_favorite(alpha)),
        "the window shows what is on disk, not the edit that was not kept"
    );
}

#[gpui::test]
async fn an_applied_backup_waits_for_a_running_sync_and_is_uploaded(cx: &mut TestAppContext) {
    let server = shellune_sync::testing::WebDavServer::start(SYNC_USER, SYNC_PASSWORD);
    let dir = TempDir::new("backup-then-sync");
    seed(
        &dir.store(),
        vec![stored_host("alpha", "10.0.0.1", 22, "root", None)],
    );
    let backup = dir.path().join("backup.json");
    write_backup(
        &backup,
        vec![stored_host("beta", "10.0.0.2", 22, "root", None)],
        None,
        &[],
    );
    let secrets = Arc::new(shellune_storage::MemorySecrets::new());
    configure_sync(&dir, &secrets, &server, true);
    let (view, cx) = sync_window(cx, &dir, &secrets, Destination::Settings);
    assert_eq!(cloud_host_names(&server), vec!["alpha"]);

    // A check is running (held once it ends) when the import is applied.
    hold_sync_finish(&view, cx);
    cx.update(|_window, app| view.update(app, |view, cx| view.check_sync_for_test(cx)));
    cx.run_until_parked();
    assert!(sync_finish_held(&view, cx));
    read_backup(&view, cx, &backup);
    assert_eq!(backup_stage(&view, cx), Some("import.preview"));
    click(cx, "backup.import.apply");
    assert_eq!(
        backup_stage(&view, cx),
        Some("import.applying"),
        "the import waits for the slot the sync holds"
    );
    assert_eq!(
        names_on_disk(&dir),
        vec!["alpha"],
        "nothing is applied while the sync holds the slot"
    );

    release_sync_finish(&view, cx);
    assert_eq!(backup_stage(&view, cx), Some("import.applied"));
    assert_eq!(names_on_disk(&dir), vec!["alpha", "beta"]);
    assert_eq!(host_names(&view, cx), vec!["alpha", "beta"]);
    assert_eq!(
        cloud_host_names(&server),
        vec!["alpha"],
        "nothing is sent before the debounce runs out"
    );
    after_debounce(cx);
    assert_eq!(
        cloud_host_names(&server),
        vec!["alpha", "beta"],
        "the imported data is uploaded like any other change"
    );
    assert_eq!(sync_marker(&view, cx), None);
}

#[gpui::test]
async fn a_failed_sync_is_retried_after_a_minute_then_less_often(cx: &mut TestAppContext) {
    let server = shellune_sync::testing::WebDavServer::start(SYNC_USER, SYNC_PASSWORD);
    let dir = TempDir::new("sync-backoff");
    seed(
        &dir.store(),
        vec![stored_host("alpha", "10.0.0.1", 22, "root", None)],
    );
    let secrets = Arc::new(shellune_storage::MemorySecrets::new());
    configure_sync(&dir, &secrets, &server, true);
    let (view, cx) = sync_window(cx, &dir, &secrets, Destination::Hosts);
    assert_eq!(cloud_host_names(&server), vec!["alpha"]);

    server.set_offline(true);
    let alpha = first_host_id(&view, cx);
    toggle_favorite(&view, cx, alpha);
    after_debounce(cx);
    let (failed_once, _, failure) = sync_progress(&view, cx);
    assert!(failure.is_some());
    let advance = |cx: &mut VisualTestContext, seconds: u64| {
        cx.executor()
            .advance_clock(std::time::Duration::from_secs(seconds));
        cx.run_until_parked();
    };

    advance(cx, 61);
    assert_eq!(
        sync_progress(&view, cx).0,
        failed_once + 1,
        "the first retry comes after a minute"
    );
    advance(cx, 61);
    assert_eq!(
        sync_progress(&view, cx).0,
        failed_once + 1,
        "the next waits twice as long"
    );
    advance(cx, 60);
    assert_eq!(sync_progress(&view, cx).0, failed_once + 2);

    // The network is back; the next retry - well before the 15-minute check - sends it.
    server.set_offline(false);
    advance(cx, 241);
    assert_eq!(sync_progress(&view, cx).0, failed_once + 3);
    assert_eq!(sync_progress(&view, cx).2, None);
    assert_eq!(sync_marker(&view, cx), None);
    assert!(cloud_document(&server).shared().hosts().is_favorite(alpha));

    // A success ends the retries (the 15-minute check is still minutes away).
    let settled = sync_progress(&view, cx).0;
    advance(cx, 5 * 60);
    assert_eq!(
        sync_progress(&view, cx).0,
        settled,
        "nothing is retried after a success"
    );
}

