#[gpui::test]
async fn the_shortcut_capture_is_the_shared_dialog_and_a_press_outside_cancels_it(
    cx: &mut TestAppContext,
) {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    cx.update(|_window, app| app.bind_keys(key_bindings(Platform::current())));
    cx.simulate_resize(tall_window());
    cx.run_until_parked();
    click(cx, "nav.settings");
    click(cx, "settings.category.keys");
    click(cx, "settings.keys.change.nav.settings");

    // The capture is drawn in the shared dialog, over a dimmed window (R5).
    assert!(cx.debug_bounds("keys.capture").is_some());
    assert!(
        cx.debug_bounds("keys.capture.dialog.backdrop").is_some(),
        "the capture dims the window behind it"
    );
    let dialog = bounds_of(cx, "keys.capture.dialog");
    assert_inside_box(
        bounds_of(cx, "keys.capture.cancel"),
        dialog,
        "keys.capture.cancel",
    );

    // Nothing typed can be lost here, so a press on the dimmed window outside the
    // dialog is a way out, as it was before, and the binding is untouched.
    let corner = point(
        dialog.origin.x / 2.0,
        dialog.origin.y + dialog.size.height / 2.0,
    );
    cx.simulate_click(corner, Modifiers::default());
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| view.read(app).capturing_for()),
        None,
        "a press outside the dialog cancels the capture"
    );
    assert_eq!(
        cx.update(|_window, app| view
            .read(app)
            .keymap()
            .keystroke("nav.settings")
            .map(str::to_owned)),
        Keymap::defaults(Platform::current())
            .keystroke("nav.settings")
            .map(str::to_owned),
        "cancelling leaves the binding as it was"
    );
}

/// Sets the window's motion preference to `motion`, by the same step the settings use.
fn motion_to(view: &Entity<ShelluneView>, cx: &mut VisualTestContext, motion: Motion) {
    while cx.update(|_window, app| view.read(app).workspace().motion()) != motion {
        cx.update(|_window, app| view.update(app, |view, cx| view.cycle_motion(cx)));
        cx.run_until_parked();
    }
}

#[gpui::test]
async fn a_closed_dialog_leaves_its_dimming_to_fade_out_and_the_page_usable(
    cx: &mut TestAppContext,
) {
    let dir = TempDir::new("scrim-exit");
    let store = dir.store();
    seed(
        &store,
        vec![
            stored_host("web", "10.0.0.5", 22, "deploy", None),
            stored_host("db", "10.0.0.6", 22, "postgres", None),
        ],
    );
    let (view, cx) = hosts_view(cx, store);
    motion_to(&view, cx, Motion::Full);
    // Whether the window draws a fading dimming now. Asked of the view: a test frame
    // keeps the bounds of what an earlier frame drew.
    let fading =
        |cx: &mut VisualTestContext| cx.update(|_window, app| view.read(app).scrim_exit_for_test());
    let dialog = |cx: &mut VisualTestContext| {
        cx.update(|_window, app| view.read(app).modal_shown_for_test())
    };

    // Nothing has closed yet, so nothing fades.
    assert!(!fading(cx));
    click(cx, "hosts.delete.0");
    assert!(cx.debug_bounds("hosts.confirm.backdrop").is_some());
    assert!(
        !fading(cx),
        "an open dialog has its own dimming, not a fading one"
    );

    // Escape answers the question: the dialog goes at once and its dimming fades out
    // over the window (R5).
    cx.simulate_keystrokes("escape");
    cx.run_until_parked();
    assert!(!dialog(cx), "the card goes at once");
    assert!(fading(cx), "the dimming stays behind to fade out");
    let viewport = cx.update(|window, _app| window.viewport_size());
    let scrim = bounds_of(cx, "modal.scrim.exit");
    assert!(
        scrim.size.width >= viewport.width - px(0.5)
            && scrim.size.height >= viewport.height - px(0.5),
        "the fading dimming covers the window it dimmed: {scrim:?} in {viewport:?}"
    );

    // The fading dimming takes no presses: the page is usable the moment the question
    // is answered, and a new dialog brings its own dimming.
    click(cx, "hosts.delete.1");
    assert!(
        cx.update(|_window, app| view.read(app).hosts_state().pending_delete().is_some())
            && dialog(cx),
        "a press through the fading dimming reaches the page"
    );
    assert!(!fading(cx), "a dialog that opens ends the fade");

    // The fade is gone once its time is up.
    click(cx, "hosts.confirm.cancel");
    assert!(!dialog(cx) && fading(cx));
    cx.executor()
        .advance_clock(crate::app::components::SCRIM_EXIT + std::time::Duration::from_millis(20));
    cx.run_until_parked();
    assert!(!fading(cx), "the dimming is gone once it has faded");

    // A form closes the same way.
    click(cx, "hosts.new");
    assert!(cx.debug_bounds("hosts.editor.backdrop").is_some());
    cx.simulate_keystrokes("escape");
    cx.run_until_parked();
    assert!(!dialog(cx), "Escape closes the form");
    assert!(fading(cx), "a closed form's dimming fades out too");
    cx.executor()
        .advance_clock(crate::app::components::SCRIM_EXIT + std::time::Duration::from_millis(20));
    cx.run_until_parked();
    assert!(!fading(cx));

    // With reduced motion the dimming goes with the dialog.
    motion_to(&view, cx, Motion::Reduced);
    click(cx, "hosts.delete.0");
    assert!(dialog(cx));
    cx.simulate_keystrokes("escape");
    cx.run_until_parked();
    assert!(!dialog(cx), "Escape closes the question");
    assert!(
        !fading(cx),
        "reduced motion leaves no fading dimming behind"
    );
    motion_to(&view, cx, Motion::Full);
}

#[gpui::test]
async fn a_delete_question_keeps_every_key_but_escape(cx: &mut TestAppContext) {
    let dir = TempDir::new("question-keys");
    seed(
        &dir.store(),
        vec![
            stored_host("web", "10.0.0.5", 22, "deploy", None),
            stored_host("db", "10.0.0.9", 22, "postgres", None),
        ],
    );
    let (view, cx) = hosts_view_with_trust(cx, &dir);
    cx.update(|_window, app| app.bind_keys(key_bindings(Platform::current())));
    type_into(cx, "hosts.search", "db");
    let search = |cx: &mut VisualTestContext| {
        cx.update(|_window, app| view.read(app).hosts_state().search().to_owned())
    };
    assert_eq!(search(cx), "db");

    // The question is asked while the search field still holds the keyboard.
    cx.update(|_window, app| {
        view.update(app, |view, cx| {
            let id = view.book().hosts()[1].id();
            view.request_delete_host_for_test(id, cx);
        });
    });
    cx.run_until_parked();
    assert!(cx.debug_bounds("hosts.confirm").is_some());

    // Enter behind the question would connect the match the user cannot see; typed
    // text would change the search under it; a shortcut would act behind it. All of
    // them are spent on the question, which stays open (R5).
    cx.simulate_keystrokes("enter");
    cx.simulate_keystrokes("x");
    cx.simulate_keystrokes("ctrl-l");
    cx.run_until_parked();
    assert!(
        cx.update(|_window, app| view.read(app).remote_state().is_none()),
        "Enter behind the question connects nothing"
    );
    assert_eq!(
        search(cx),
        "db",
        "typed text does not reach the field behind"
    );
    assert_eq!(
        cx.update(|_window, app| view.read(app).workspace().locale()),
        Locale::English,
        "no shortcut runs behind the question"
    );
    assert!(
        cx.update(|_window, app| view.read(app).question_open()),
        "only an answer closes the question"
    );
    assert_eq!(
        cx.update(|_window, app| view.read(app).book().hosts().len()),
        2,
        "no key deletes anything"
    );

    // Escape is the way out, and the keys belong to the page again after it.
    cx.simulate_keystrokes("escape");
    cx.run_until_parked();
    assert!(!cx.update(|_window, app| view.read(app).question_open()));
    assert_eq!(
        cx.update(|_window, app| view.read(app).book().hosts().len()),
        2
    );
    cx.simulate_keystrokes("ctrl-l");
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| view.read(app).workspace().locale()),
        Locale::Chinese,
        "shortcuts run again once the question is answered"
    );
}

#[gpui::test]
async fn the_palette_settles_like_a_dialog_and_its_dimming_fades_on_close(cx: &mut TestAppContext) {
    // The palette is a dialog-level layer: it is drawn on the dialog surface and,
    // closed, leaves its dimming to fade out like every dialog's does (R5, R6).
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    cx.simulate_resize(design_window());
    cx.run_until_parked();
    motion_to(&view, cx, Motion::Full);
    let fading =
        |cx: &mut VisualTestContext| cx.update(|_window, app| view.read(app).scrim_exit_for_test());

    go(cx, crate::app::actions::OpenPalette);
    assert!(cx.update(|_window, app| view.read(app).palette_open()));
    assert!(cx.debug_bounds("palette").is_some());
    assert!(!fading(cx), "an open palette has its own dimming");

    cx.simulate_keystrokes("escape");
    cx.run_until_parked();
    assert!(!cx.update(|_window, app| view.read(app).palette_open()));
    assert!(fading(cx), "the palette's dimming stays behind to fade out");
    cx.executor()
        .advance_clock(crate::app::components::SCRIM_EXIT + std::time::Duration::from_millis(20));
    cx.run_until_parked();
    assert!(!fading(cx), "and is gone once it has faded");

    // Reduced motion leaves nothing behind.
    motion_to(&view, cx, Motion::Reduced);
    go(cx, crate::app::actions::OpenPalette);
    cx.simulate_keystrokes("escape");
    cx.run_until_parked();
    assert!(
        !fading(cx),
        "reduced motion takes the dimming with the palette"
    );
    motion_to(&view, cx, Motion::Full);
}

#[gpui::test]
async fn a_host_menu_is_the_shared_menu_card_with_every_entry_inside_it(cx: &mut TestAppContext) {
    // The host row's menu is drawn from the shared card and entries: every command is
    // inside the card, one under the other in reading order, and the card stays in the
    // window (R6).
    let dir = TempDir::new("host-menu-card");
    let store = dir.store();
    seed(
        &store,
        vec![
            stored_host("web", "10.0.0.5", 22, "deploy", None),
            stored_host("db", "10.0.0.6", 22, "postgres", None),
        ],
    );
    let (view, cx) = hosts_view(cx, store);
    right_click(cx, "hosts.row.0");
    assert!(cx.update(|_window, app| view.read(app).host_menu_open()));
    let menu = bounds_of(cx, "host.menu");
    let viewport = cx.update(|window, _app| window.viewport_size());
    assert!(
        menu.right() <= viewport.width && menu.bottom() <= viewport.height,
        "the menu stays inside the window: {menu:?} in {viewport:?}"
    );
    let mut above: Option<gpui::Bounds<Pixels>> = None;
    for entry in [
        "host.menu.connect",
        "host.menu.forwards",
        "host.menu.favorite",
        "host.menu.copy_target",
        "host.menu.edit",
        "host.menu.duplicate",
        "host.menu.delete",
    ] {
        let bounds = bounds_of(cx, entry);
        assert!(
            bounds.left() >= menu.left()
                && bounds.right() <= menu.right()
                && bounds.top() >= menu.top()
                && bounds.bottom() <= menu.bottom(),
            "{entry} is inside the card: {bounds:?} in {menu:?}"
        );
        assert!(
            bounds.size.height >= px(24.0),
            "{entry} keeps the pointer target"
        );
        if let Some(above) = above {
            assert!(
                bounds.top() >= above.bottom() - px(0.5),
                "{entry} is under the entry before it"
            );
        }
        above = Some(bounds);
    }
    cx.simulate_keystrokes("escape");
    cx.run_until_parked();
    assert!(!cx.update(|_window, app| view.read(app).host_menu_open()));
}

#[gpui::test]
async fn the_selection_bar_lays_its_actions_in_a_row_inside_it(cx: &mut TestAppContext) {
    // The marks' banner is a row: what the marks cover, then the actions side by side.
    // It used to stack every action under the other across the whole column, with the
    // hint cut to an ellipsis (R6, R14).
    let (view, cx) = remote_view(cx);
    let id = live_remote(cx, &view);
    let _ = open_both_sources(
        cx,
        &view,
        id,
        "/C:/work",
        &[("a.txt", shellune_core::FileKind::File)],
    );
    click(cx, "files.mark.0");
    click(cx, "files.mark.1");
    let bar = bounds_of(cx, "files.selection");
    let count = bounds_of(cx, "files.selection.count");
    let actions = [
        "files.mark.download",
        "files.mark.copy",
        "files.mark.delete",
        "files.mark.clear",
    ]
    .map(|selector| (selector, bounds_of(cx, selector)));
    let first = actions[0].1;
    for (selector, bounds) in actions {
        assert!(
            bounds.left() >= bar.left()
                && bounds.right() <= bar.right()
                && bounds.bottom() <= bar.bottom(),
            "{selector} is inside the bar: {bounds:?} in {bar:?}"
        );
        assert!(
            (bounds.top() - first.top()).abs() < px(1.0),
            "{selector} sits in the actions' one row"
        );
        assert!(
            bounds.size.width < bar.size.width / 2.0,
            "{selector} is a button, not a full-width row"
        );
        assert!(
            bounds.top() >= count.bottom(),
            "{selector} follows the count"
        );
    }
    for pair in actions.windows(2) {
        assert!(
            pair[1].1.left() >= pair[0].1.right(),
            "{} is beside {}, not under it",
            pair[1].0,
            pair[0].0
        );
    }
}

#[gpui::test]
async fn the_selection_bar_wraps_its_actions_inside_it_at_720x480_and_200_percent(
    cx: &mut TestAppContext,
) {
    // At the minimum window and the largest text the four actions are wider than the
    // column. The group has to wrap inside the bar rather than run past its right edge
    // and out of the window (R6, R9). The rows are marked in the design window, where
    // they are on screen, and the bar is measured after the window shrinks.
    let (view, cx) = remote_view(cx);
    let id = live_remote(cx, &view);
    let _ = open_both_sources(
        cx,
        &view,
        id,
        "/C:/work",
        &[
            ("a.txt", shellune_core::FileKind::File),
            ("b.txt", shellune_core::FileKind::File),
        ],
    );
    for mark in [
        "files.mark.0",
        "files.mark.1",
        "files.local.mark.0",
        "files.local.mark.1",
    ] {
        click(cx, mark);
    }
    cx.simulate_resize(minimum_window());
    cx.run_until_parked();
    largest_text_size(&view, cx);
    cx.run_until_parked();
    let viewport = minimum_window();
    let columns: [(&'static str, [&'static str; 4]); 2] = [
        (
            "files.selection",
            [
                "files.mark.download",
                "files.mark.copy",
                "files.mark.delete",
                "files.mark.clear",
            ],
        ),
        (
            "files.local.selection",
            [
                "files.local.mark.upload",
                "files.local.mark.copy",
                "files.local.mark.delete",
                "files.local.mark.clear",
            ],
        ),
    ];
    for (bar_selector, actions) in columns {
        let bar = bounds_of(cx, bar_selector);
        assert_within_width(bar, viewport, bar_selector);
        for selector in actions {
            let bounds = bounds_of(cx, selector);
            assert!(
                bounds.left() >= bar.left() - px(0.5)
                    && bounds.right() <= bar.right() + px(0.5)
                    && bounds.top() >= bar.top() - px(0.5)
                    && bounds.bottom() <= bar.bottom() + px(0.5),
                "{selector} is inside the bar: {bounds:?} in {bar:?}"
            );
            assert_within_width(bounds, viewport, selector);
        }
    }
}

// ---------------------------------------------------------------------------
// The window's start: four stages, a bar that follows them, then the page (R3)
// ---------------------------------------------------------------------------

/// A window built the way a launch builds it, over `store`, at the design size.
fn launching_view(
    cx: &mut TestAppContext,
    workspace: Workspace,
    store: HostStore,
) -> (Entity<ShelluneView>, &mut VisualTestContext) {
    let (view, cx) = cx
        .add_window_view(move |_window, cx| ShelluneView::launching_for_test(cx, workspace, store));
    cx.simulate_resize(design_window());
    (view, cx)
}

fn starting(view: &Entity<ShelluneView>, cx: &mut VisualTestContext) -> bool {
    cx.update(|_window, app| view.read(app).starting())
}

fn splash_fading(view: &Entity<ShelluneView>, cx: &mut VisualTestContext) -> bool {
    cx.update(|_window, app| view.read(app).splash_fading())
}

fn page_entering(view: &Entity<ShelluneView>, cx: &mut VisualTestContext) -> bool {
    cx.update(|_window, app| view.read(app).page_entering())
}

/// The stages that reported so far, with whether each failed.
fn startup_stages(
    view: &Entity<ShelluneView>,
    cx: &mut VisualTestContext,
) -> Vec<(crate::app::view::StartupStage, bool)> {
    cx.update(|_window, app| {
        view.read(app)
            .startup_reports()
            .into_iter()
            .map(|report| (report.stage, report.failure.is_some()))
            .collect()
    })
}

fn startup_target(view: &Entity<ShelluneView>, cx: &mut VisualTestContext) -> f32 {
    cx.update(|_window, app| view.read(app).startup_target())
}

fn startup_stop(
    view: &Entity<ShelluneView>,
    cx: &mut VisualTestContext,
) -> Option<crate::app::view::StartupStage> {
    cx.update(|_window, app| view.read(app).startup_stop())
}

/// The reason the stage that failed gave.
fn startup_failure(view: &Entity<ShelluneView>, cx: &mut VisualTestContext) -> String {
    cx.update(|_window, app| {
        view.read(app)
            .startup_reports()
            .into_iter()
            .find_map(|report| report.failure)
            .unwrap_or_default()
    })
}

#[gpui::test]
async fn a_launch_runs_the_four_stages_in_order_then_fades_into_the_page(cx: &mut TestAppContext) {
    use crate::app::view::{BRAND_ENTRANCE, PAGE_ENTRANCE, SPLASH_EXIT, StartupStage};
    let dir = TempDir::new("startup-splash");
    seed(
        &dir.store(),
        vec![stored_host("web", "10.0.0.5", 22, "deploy", None)],
    );
    let mut workspace = Workspace::new();
    workspace.select(Destination::Hosts);
    let (view, cx) = launching_view(cx, workspace, dir.store());
    cx.run_until_parked();
    assert_eq!(
        startup_stages(&view, cx),
        vec![
            (StartupStage::Settings, false),
            (StartupStage::Hosts, false),
            (StartupStage::Workspace, false),
            (StartupStage::Interface, false),
        ],
        "the four stages report one after another, in order"
    );
    assert!(
        (startup_target(&view, cx) - 1.0).abs() < f32::EPSILON,
        "the bar's target is full once the four are behind"
    );

    // The stages are over, but the brand has not had its entrance yet: the window stays
    // on its start, with nothing of the page drawn.
    assert!(starting(&view, cx), "the brand is shown for its entrance");
    for selector in [
        "startup.splash",
        "startup.splash.brand",
        "startup.splash.mark",
        "startup.splash.name",
        "startup.progress",
        "startup.stage",
    ] {
        assert!(cx.debug_bounds(selector).is_some(), "{selector} is drawn");
    }
    assert!(
        cx.debug_bounds("hosts.search").is_none() && cx.debug_bounds("topbar").is_none(),
        "the page is not drawn behind the brand"
    );
    assert_eq!(
        cx.update(|_window, app| view.read(app).workspace().state(Destination::Hosts)),
        SectionState::Loading,
        "nothing read is adopted before the start ends"
    );

    cx.executor().advance_clock(BRAND_ENTRANCE);
    cx.run_until_parked();
    assert!(!starting(&view, cx), "the entrance over, the page is shown");
    assert!(
        splash_fading(&view, cx),
        "the start fades out over the page"
    );
    assert!(page_entering(&view, cx), "and the page fades in under it");
    assert!(cx.debug_bounds("startup.crossfade").is_some());
    assert!(
        cx.debug_bounds("hosts.search").is_some() && cx.debug_bounds("topbar").is_some(),
        "the page is drawn under the fading start"
    );
    cx.update(|_window, app| {
        let workspace = view.read(app).workspace();
        assert_eq!(workspace.state(Destination::Hosts), SectionState::Populated);
        assert_eq!(workspace.item_count(Destination::Hosts), 1);
    });

    cx.executor().advance_clock(SPLASH_EXIT);
    cx.run_until_parked();
    // The window keeps the bounds of everything it once drew, so the end of the fade
    // is read from the state the render draws the layer from.
    assert!(
        !splash_fading(&view, cx),
        "the fade ends after 200 ms and nothing of the start is left over the page"
    );
    assert!(page_entering(&view, cx), "the page takes 300 ms to arrive");
    cx.executor()
        .advance_clock(PAGE_ENTRANCE + crate::app::view::PAGE_STAGGER - SPLASH_EXIT);
    cx.run_until_parked();
    assert!(
        !page_entering(&view, cx),
        "and then it is in place, the list 40 ms after the sidebar"
    );
}

/// How far the home's sidebar and list were drawn below their places on the first frame
/// after the start: with full motion both rise into place, the list just after the
/// sidebar; with reduced motion they only fade.
fn page_rise(motion: Motion, cx: &mut TestAppContext) -> (Pixels, Pixels) {
    use crate::app::view::{BRAND_ENTRANCE, PAGE_ENTRANCE, PAGE_STAGGER};
    let dir = TempDir::new("startup-rise");
    seed(
        &dir.store(),
        vec![stored_host("web", "10.0.0.5", 22, "deploy", None)],
    );
    let mut workspace = Workspace::new();
    workspace.select(Destination::Hosts);
    workspace.set_motion(motion);
    let (view, cx) = launching_view(cx, workspace, dir.store());
    cx.run_until_parked();
    cx.executor().advance_clock(BRAND_ENTRANCE);
    cx.run_until_parked();
    assert!(!starting(&view, cx));
    assert!(page_entering(&view, cx));
    let sidebar_arriving = bounds_of(cx, "home.sidebar");
    let list_arriving = bounds_of(cx, "hosts.search");
    cx.executor().advance_clock(PAGE_ENTRANCE + PAGE_STAGGER);
    cx.run_until_parked();
    assert!(!page_entering(&view, cx));
    let sidebar = bounds_of(cx, "home.sidebar");
    let list = bounds_of(cx, "hosts.search");
    (
        sidebar_arriving.origin.y - sidebar.origin.y,
        list_arriving.origin.y - list.origin.y,
    )
}

#[gpui::test]
async fn with_full_motion_the_sidebar_and_the_list_rise_into_place(cx: &mut TestAppContext) {
    let (sidebar, list) = page_rise(Motion::Full, cx);
    let travel = px(crate::app::view::PAGE_TRAVEL);
    // The rise follows the wall clock, not the test's, so only its direction and its
    // ceiling are certain: each piece was drawn lower, by no more than 8 px, and the
    // list, which starts later, no higher than the sidebar.
    for (piece, rise) in [("sidebar", sidebar), ("list", list)] {
        assert!(
            rise > px(0.25) && rise <= travel + px(0.5),
            "the {piece} starts up to 8 px lower and rises: {rise:?}"
        );
    }
    assert!(
        list >= sidebar - px(0.25),
        "the list follows the sidebar: {list:?} after {sidebar:?}"
    );
}

#[gpui::test]
async fn with_reduced_motion_the_page_only_fades_in(cx: &mut TestAppContext) {
    let (sidebar, list) = page_rise(Motion::Reduced, cx);
    assert!(
        sidebar.abs() < px(0.5) && list.abs() < px(0.5),
        "reduced motion moves nothing: {sidebar:?}, {list:?}"
    );
}

